/* builder.workbench.js — workbench builder: click a rendered element to jump
   to its definition in the spec editor (with per-element authoring guidance),
   and insert ready-made node/edge/step/panel/section snippets.

   The top half is pure text/JSON utilities (unit-tested in
   tests/builder.test.js); initWorkbenchBuilder at the bottom wires the DOM
   and is only called by boot.workbench.js. */

/* ---------------- Mermaid sequence skeleton ---------------- */

function mermaidToSpec(text){
  if (typeof text !== 'string') throw new Error('line 1: expected mermaid text');
  /* Match the CLI: the first mermaid fence wins, even if it is not a sequence. */
  var fence = /^```mermaid\s*$([\s\S]*?)^```\s*$/m.exec(text);
  var lines = (fence ? fence[1] : text).split(/\r\n|[\n\r\v\f\x1c-\x1e\x85\u2028\u2029]/)
    .map(function(ln){ return ln.trim(); }).filter(function(ln){ return ln; });
  if (!lines.length || lines[0] !== 'sequenceDiagram')
    throw new Error('line 1: not a sequenceDiagram (first line is ' +
      JSON.stringify(lines[0] || '<empty>') + '); only mermaid sequenceDiagram input is supported');
  var order = [], titles = Object.create(null), messages = [], todos = [];
  var depth = 0, skipped = 0, header = null, blockLine = 0, n = 1;
  function ensure(pid, title){
    var id = pid.toLowerCase().replace(/[^a-z0-9]+/g, '');
    if (!id) throw new Error('line ' + n + ': participant id ' + JSON.stringify(pid) + ' slugs to nothing');
    if (!Object.prototype.hasOwnProperty.call(titles, id)){
      order.push(id);
      titles[id] = title || pid;
    } else if (title) titles[id] = title;
    return id;
  }
  for (var i = 1; i < lines.length; i++){
    var ln = lines[i];
    n = i + 1; /* CLI line numbers count nonblank lines. */
    if (ln === 'autonumber') continue;
    if (/^Note\b/i.test(ln)){
      todos.push('note not converted: ' + ln);
      continue;
    }
    var b = /^(alt|opt|loop|par)\b\s*(.*)$/.exec(ln);
    if (b){
      if (!depth){ header = (b[1] + ' ' + b[2]).trim(); skipped = 0; blockLine = n; }
      depth++;
      continue;
    }
    if (ln === 'else' || ln.indexOf('else ') === 0){
      if (!depth) throw new Error('line ' + n + ": 'else' outside a block");
      continue;
    }
    if (ln === 'end'){
      if (!depth) throw new Error('line ' + n + ": 'end' without an open block");
      depth--;
      if (!depth) todos.push(header + ' block not converted (' + skipped + ' message(s) inside) — add by hand');
      continue;
    }
    var p = /^participant\s+(\S+?)(?:\s+as\s+(.+?))?\s*$/.exec(ln);
    if (p){
      if (!depth) ensure(p[1], p[2]);
      continue;
    }
    var m = /^(\S+?)\s*(-->>|->>)\s*(\S+?)\s*:\s*(.+?)\s*$/.exec(ln);
    if (m){
      if (depth){ skipped++; continue; }
      messages.push({from: ensure(m[1]), to: ensure(m[3]), ret: m[2] === '-->>', text: m[4]});
      continue;
    }
    throw new Error('line ' + n + ': unsupported syntax ' + JSON.stringify(ln) +
      ' — supported: participant, ->> / -->> messages, autonumber, alt/opt/loop/par blocks, Note');
  }
  if (depth) throw new Error('line ' + blockLine + ': unclosed alt/opt/loop/par block');
  if (!messages.length) throw new Error('line ' + n + ': no messages found outside alt/opt/loop/par blocks');
  var edges = [], pairs = Object.create(null), steps = [];
  messages.forEach(function(m){
    var key = m.from + '->' + m.to;
    if (!pairs[key]){
      var kind = /https?|POST|GET/i.test(m.text) ? 'https' :
        /publish|subscribe|mqtt|qos/i.test(m.text) ? 'mqtt' : 'int';
      var edge = {from: m.from, to: m.to, kind: kind, label: m.text};
      if (m.ret) edge.ret = true;
      pairs[key] = true;
      edges.push(edge);
    }
    steps.push({edge: key, text: m.text});
  });
  var half = Math.floor((order.length + 1) / 2), rows = [order.slice(0, half)], nodes = {};
  if (order.length > half) rows.push(order.slice(half));
  order.forEach(function(id){ nodes[id] = {title: titles[id], sub: '', icon: 'gear', tint: 'cmd'}; });
  var title = 'Converted sequence';
  return {page: {title: title, sections: [{heading: title,
    text: ['Skeleton generated by mermaid2spec.py — enrich titles, subs, icons, tints, protocols, and prose before use.'],
    diagram: {view: 'ambient', nodes: nodes, rows: rows, edges: edges, steps: steps}
  }]}, todos: todos};
}

/* ---------------- JSON source locator ----------------
   A tolerant scanner over the RAW editor text: given a path (array of object
   keys / array indices), find the character range of the value so the
   textarea can select it. Whitespace-agnostic; strings with escapes are
   skipped correctly. On duplicate keys the FIRST occurrence wins (JSON.parse
   keeps the last — hand-authored specs do not duplicate keys, and a miss
   only mis-places the selection). */

function jsonSkipWS(text, i){
  while (i < text.length && ' \t\n\r'.indexOf(text[i]) >= 0) i++;
  return i;
}
function jsonSkipString(text, i){
  /* i at the opening quote; returns the index just past the closing quote */
  i++;
  while (i < text.length){
    if (text[i] === '\\') i += 2;
    else if (text[i] === '"') return i + 1;
    else i++;
  }
  return i;
}
function jsonSkipValue(text, i){
  /* i at the first char of a value; returns the index just past it */
  i = jsonSkipWS(text, i);
  var c = text[i];
  if (c === '"') return jsonSkipString(text, i);
  if (c === '{' || c === '['){
    var open = c, close = c === '{' ? '}' : ']', depth = 0;
    while (i < text.length){
      c = text[i];
      if (c === '"'){ i = jsonSkipString(text, i); continue; }
      if (c === open) depth++;
      else if (c === close){ depth--; if (!depth) return i + 1; }
      i++;
    }
    return i;
  }
  while (i < text.length && ',}] \t\n\r'.indexOf(text[i]) < 0) i++;
  return i;
}
function jsonContainer(text, i){
  /* Parse the container ({...} or [...]) starting at/after i. Returns
     {isObj, open, close, members:[{key, keyStart, valStart, valEnd}]} —
     key is the decoded object key or the array index — or null. */
  i = jsonSkipWS(text, i);
  var c = text[i];
  if (c !== '{' && c !== '[') return null;
  var isObj = c === '{';
  var members = [];
  var j = i + 1, idx = 0;
  while (j < text.length){
    j = jsonSkipWS(text, j);
    if (j >= text.length) break;
    var ch = text[j];
    if (ch === (isObj ? '}' : ']')) return {isObj: isObj, open: i, close: j, members: members};
    if (ch === ','){ j++; continue; }
    if (isObj){
      if (ch !== '"'){ j++; continue; }
      var keyStart = j, keyEnd = jsonSkipString(text, j);
      var key;
      try { key = JSON.parse(text.slice(keyStart, keyEnd)); } catch (ex){ key = null; }
      j = jsonSkipWS(text, keyEnd);
      if (text[j] === ':') j++;
      j = jsonSkipWS(text, j);
      var valStart = j, valEnd = jsonSkipValue(text, j);
      members.push({key: key, keyStart: keyStart, valStart: valStart, valEnd: valEnd});
      j = valEnd;
    } else {
      var vs = jsonSkipWS(text, j), ve = jsonSkipValue(text, vs);
      members.push({key: idx++, keyStart: vs, valStart: vs, valEnd: ve});
      j = ve;
    }
  }
  return null; /* unterminated container */
}
function jsonLocate(text, path){
  /* Character range {start, end, keyStart} of the value at path; [] means
     the whole document. null when any path segment is absent. */
  var start = jsonSkipWS(text, 0);
  if (start >= text.length) return null;
  var node = {keyStart: start, valStart: start, valEnd: jsonSkipValue(text, start)};
  for (var p = 0; p < path.length; p++){
    var cont = jsonContainer(text, node.valStart);
    if (!cont) return null;
    var found = null;
    for (var m = 0; m < cont.members.length; m++){
      if (cont.members[m].key === path[p]){ found = cont.members[m]; break; }
    }
    if (!found) return null;
    node = found;
  }
  return {start: node.valStart, end: node.valEnd, keyStart: node.keyStart};
}

/* ---------------- insertion ---------------- */

function jsonIndentFor(text, cont){
  /* Indent for a new member: copy the last member's line indent, else the
     opening bracket's line indent plus two spaces. */
  var anchor = cont.members.length ? cont.members[cont.members.length - 1].keyStart : -1;
  if (anchor < 0){
    var ls = text.lastIndexOf('\n', cont.open) + 1;
    return (text.slice(ls, cont.open).match(/^[ \t]*/) || [''])[0] + '  ';
  }
  var ls2 = text.lastIndexOf('\n', anchor) + 1;
  return (text.slice(ls2, anchor).match(/^[ \t]*/) || [''])[0];
}
function jsonInsertMember(text, path, keyOrNull, valueText){
  /* Append a member to the object (keyOrNull = key) or array (null) at
     path. valueText may be multi-line with two-space relative indents.
     Returns {text, start, end} — start/end select the inserted value. */
  var loc = path.length ? jsonLocate(text, path) : {start: jsonSkipWS(text, 0)};
  var cont = loc ? jsonContainer(text, loc.start) : null;
  if (!cont || cont.isObj !== (keyOrNull != null)) return null;
  var indent = jsonIndentFor(text, cont);
  var keyPart = keyOrNull != null ? JSON.stringify(keyOrNull) + ': ' : '';
  var adjVal = valueText.split('\n').join('\n' + indent);
  var insertAt, prefix;
  if (cont.members.length){
    insertAt = cont.members[cont.members.length - 1].valEnd;
    prefix = ',\n' + indent;
  } else {
    insertAt = cont.open + 1;
    prefix = '\n' + indent;
  }
  var start = insertAt + prefix.length + keyPart.length;
  return {text: text.slice(0, insertAt) + prefix + keyPart + adjVal + text.slice(insertAt),
          start: start, end: start + adjVal.length};
}
function jsonInsertListItemOrCreate(text, ownerPath, key, itemText){
  /* Append itemText to the array ownerPath.key, creating the array first
     when the key is absent. */
  var listPath = ownerPath.concat([key]);
  if (!jsonLocate(text, listPath)){
    var made = jsonInsertMember(text, ownerPath, key, '[]');
    if (!made) return null;
    text = made.text;
  }
  return jsonInsertMember(text, listPath, null, itemText);
}

/* ---------------- spec shape walking ----------------
   Mirrors normalize() + blocksOf(): the raw editor JSON may be
   {page:{blocks|sections}}, a bare {blocks|sections} page, or a bare
   diagram ({nodes, rows}). One entry per rendered section, in render
   order — the same order buildSection assigns gi. */

function specSectionPaths(raw){
  var base, page;
  if (raw && raw.page){ page = raw.page; base = ['page']; }
  else if (raw && (raw.blocks || raw.sections)){ page = raw; base = []; }
  else if (raw && raw.nodes && raw.rows) return [{section: [], diagram: []}];
  else return [];
  var key = page.blocks ? 'blocks' : 'sections';
  var out = [];
  (page[key] || []).forEach(function(b, i){
    if (b && Array.isArray(b.tabs)){
      b.tabs.forEach(function(t, j){
        ((t && Array.isArray(t.sections)) ? t.sections : []).forEach(function(sec, k){
          out.push({section: base.concat([key, i, 'tabs', j, 'sections', k])});
        });
      });
    } else out.push({section: base.concat([key, i])});
  });
  out.forEach(function(rec){ rec.diagram = rec.section.concat(['diagram']); });
  return out;
}
function specValueAt(raw, path){
  var v = raw;
  for (var i = 0; i < path.length && v != null; i++) v = v[path[i]];
  return v;
}
function starterCountLine(spec){
  var nodes = 0, steps = 0, panels = 0;
  specSectionPaths(spec).forEach(function(rec){
    var d = specValueAt(spec, rec.diagram);
    if (!d) return;
    nodes += Object.keys(d.nodes || {}).length;
    steps += (d.steps || []).length;
    panels += (d.panels || []).length;
  });
  return nodes + ' nodes · ' + steps + ' steps · ' + panels + ' panels';
}
function builderTargetPath(raw, target){
  /* target: {section:<zero-based ordinal>, kind, id?, index?} → path array
     into the raw editor JSON, or null. Tabs address by block index
     instead of section ordinal. */
  if (target.kind === 'tab') return builderTabPath(raw, target.block, target.tab);
  var rec = specSectionPaths(raw)[target.section];
  if (!rec) return null;
  if (target.kind === 'section') return rec.section;
  var d = rec.diagram;
  if (target.kind === 'node') return d.concat(['nodes', target.id]);
  if (target.kind === 'group'){
    var groups = specValueAt(raw, d.concat(['groups']));
    return groups && Object.prototype.hasOwnProperty.call(groups, target.id)
      ? d.concat(['groups', target.id]) : null;
  }
  if (target.kind === 'edge') return d.concat(['edges', target.index]);
  if (target.kind === 'step') return d.concat(['steps', target.index]);
  if (target.kind === 'panel') return d.concat(['panels', target.index]);
  if (target.kind === 'bullet') return rec.section.concat(['bullets', target.index]);
  if (target.kind === 'para'){
    var sec = specValueAt(raw, rec.section);
    if (sec && typeof sec.text === 'string') return rec.section.concat(['text']);
    return rec.section.concat(['text', target.index]);
  }
  if (target.kind === 'crow') return rec.section.concat(['contract', 'fields', target.index]);
  return null;
}

/* Search the source tree, including nodes omitted from layout and hidden
   tabs. Keep raw paths and rendered section ordinals together. */
function builderOutline(raw, query){
  var entries = [], terms = String(query || '').toLowerCase().trim().split(/\s+/).filter(Boolean);
  specSectionPaths(raw).forEach(function(rec, section){
    var sec = specValueAt(raw, rec.section) || {}, d = specValueAt(raw, rec.diagram) || {};
    var ti = rec.section.indexOf('tabs');
    var tab = ti >= 0 ? {block: rec.section[ti - 1], tab: rec.section[ti + 1]} : null;
    var parent = ti >= 0 ? specValueAt(raw, rec.section.slice(0, ti + 2)) : null;
    var context = (parent && parent.label ? parent.label + ' / ' : '') + (sec.heading || 'Section ' + (section + 1));
    function add(kind, label, extra){
      var target = Object.assign({section: section, kind: kind}, extra || {});
      var path = builderTargetPath(raw, target);
      var haystack = (kind + ' ' + label + ' ' + context + ' ' + builderPathString(path)).toLowerCase();
      if (terms.every(function(term){ return haystack.indexOf(term) >= 0; }))
        entries.push({label: label, context: context, target: target, path: path, tab: tab});
    }
    add('section', sec.heading || 'Section ' + (section + 1));
    Object.keys(d.nodes || {}).forEach(function(id){ add('node', ((d.nodes[id] || {}).title || id) + ' · ' + id, {id: id}); });
    Object.keys(d.groups || {}).forEach(function(id){ add('group', ((d.groups[id] || {}).title || id) + ' · ' + id, {id: id}); });
    (Array.isArray(d.edges) ? d.edges : []).forEach(function(e, index){
      if (e) add('edge', e.from + ' → ' + e.to + (e.label ? ' · ' + e.label : ''), {index: index});
    });
    (Array.isArray(d.panels) ? d.panels : []).forEach(function(p, index){
      if (p) add('panel', (p.title || p.id) + ' · ' + p.type + ' · ' + p.id, {index: index});
    });
    (Array.isArray(d.steps) ? d.steps : []).forEach(function(s, index){
      if (s) add('step', (index + 1) + '. ' + (s.text || s.id || 'Untitled step'), {index: index});
    });
  });
  return entries;
}
function builderPathString(path){
  return path.length ? path.map(function(seg, i){
    if (typeof seg === 'number') return '[' + seg + ']';
    return (i ? '.' : '') + (/^[A-Za-z_][A-Za-z0-9_-]*$/.test(seg) ? seg : JSON.stringify(seg));
  }).join('') : '(whole document)';
}
function builderInsertTargetText(raw, sectionIdx){
  /* the descriptive part of the insert-target label: "section N · heading",
     prefixed with the tab name when the target section lives inside a tabs
     block. A blank/whitespace tab label falls back to "tab N". Returns null
     when the section ordinal has no section. */
  var rec = specSectionPaths(raw || {})[sectionIdx];
  if (!rec) return null;
  var sec = specValueAt(raw, rec.section);
  var name = sec && typeof sec.heading === 'string' && sec.heading ? ' · ' + sec.heading : '';
  var tabName = '';
  var path = rec.section;
  var ti = path.indexOf('tabs');
  if (ti >= 0 && typeof path[ti + 1] === 'number'){
    var tabsArr = specValueAt(raw, path.slice(0, ti + 1));
    var tab = Array.isArray(tabsArr) ? tabsArr[path[ti + 1]] : null;
    var raw2 = tab && typeof tab.label === 'string' ? tab.label.trim() : '';
    var label = raw2 || ('tab ' + (path[ti + 1] + 1));
    tabName = 'tab “' + label + '” › ';
  }
  return 'into ' + tabName + 'section ' + (sectionIdx + 1) + name;
}
function builderPositionLine(raw, target){
  /* which slot the selected element occupies among its siblings — only
     the kinds with move buttons get one */
  if (!target) return null;
  if (target.kind === 'step'){
    var rec = specSectionPaths(raw)[target.section];
    if (!rec) return null;
    var d = specValueAt(raw, rec.diagram);
    if (!d || !Array.isArray(d.steps) || !d.steps[target.index]) return null;
    if (d.paths){
      var route = diagramPathList(d).find(function(p){return p.id === target.pathId && p.indices.indexOf(target.index) >= 0;}) ||
        diagramPathList(d).find(function(p){return p.indices.indexOf(target.index) >= 0;});
      if (route) return 'step ' + (route.indices.indexOf(target.index) + 1) + ' of ' + route.indices.length + ' · ' + route.label;
      return 'unused step · registry slot ' + (target.index + 1);
    }
    return 'step ' + (target.index + 1) + ' of ' + d.steps.length;
  }
  if (target.kind === 'section'){
    var n = specSectionPaths(raw).length;
    if (typeof target.section !== 'number' || target.section < 0 || target.section >= n) return null;
    return 'section ' + (target.section + 1) + ' of ' + n;
  }
  if (target.kind === 'tab'){
    var page = raw && raw.page ? raw.page : raw;
    var key = page && page.blocks ? 'blocks' : 'sections';
    var block = page && Array.isArray(page[key]) ? page[key][target.block] : null;
    if (!block || !Array.isArray(block.tabs) || !block.tabs[target.tab]) return null;
    return 'tab ' + (target.tab + 1) + ' of ' + block.tabs.length;
  }
  return null;
}

/* ---------------- insert planners ----------------
   Each takes the CURRENT editor text plus its parsed form and returns
   {text, start, end, ...} on success or {error} with a plain sentence. */

function builderUniqueKey(taken, stem){
  var n = 1;
  while (taken[stem + n]) n++;
  return stem + n;
}
function builderFlatRowIds(rows){
  var ids = [];
  (rows || []).forEach(function(row){
    (Array.isArray(row) ? row : []).forEach(function(slot){
      if (typeof slot === 'string') ids.push(slot);
      else if (Array.isArray(slot)) slot.forEach(function(s){ if (typeof s === 'string') ids.push(s); });
    });
  });
  return ids;
}
function builderDiagram(text, raw, sectionIdx){
  var rec = specSectionPaths(raw)[sectionIdx];
  if (!rec) return {error: 'no section to insert into — click a section first'};
  if (!jsonLocate(text, rec.diagram))
    return {error: 'this section has no diagram yet — add "diagram": {"nodes": {...}, "rows": [[...]]} inside it first'};
  return {path: rec.diagram, d: specValueAt(raw, rec.diagram)};
}

function planAddNode(text, raw, sectionIdx, preset){
  /* preset (optional): {icon, tint, title} from NODE_PRESETS — the id stem
     follows the icon so the spec reads well (db1, antenna1, ...) */
  var got = builderDiagram(text, raw, sectionIdx);
  if (got.error) return got;
  var d = got.d;
  if (!Array.isArray(d.rows) || !d.rows.length)
    return {error: 'this diagram has no rows — a node needs a row slot to render'};
  var icon = preset && preset.icon ? preset.icon : 'gear';
  var tint = preset && preset.tint ? preset.tint : 'cmd';
  var title = preset && preset.title ? preset.title : 'New node';
  var id = builderUniqueKey(d.nodes || {}, preset && preset.icon ? preset.icon : 'node');
  var r1 = jsonInsertMember(text, got.path.concat(['rows', d.rows.length - 1]), null, JSON.stringify(id));
  if (!r1) return {error: 'could not edit rows in the editor text'};
  var r2 = jsonInsertMember(r1.text, got.path.concat(['nodes']), id,
    '{"title": ' + JSON.stringify(title) + ', "sub": "what it does", "icon": ' +
    JSON.stringify(icon) + ', "tint": ' + JSON.stringify(tint) + '}');
  if (!r2) return {error: 'could not edit nodes in the editor text'};
  return {text: r2.text, start: r2.start, end: r2.end, kind: 'node', id: id};
}
function planAddEdge(text, raw, sectionIdx){
  var got = builderDiagram(text, raw, sectionIdx);
  if (got.error) return got;
  var ids = builderFlatRowIds(got.d.rows);
  if (ids.length < 2) return {error: 'an edge needs two placed nodes — add nodes first'};
  /* the engine keys edges by "from->to", so a duplicate pair overrides the
     first edge's animation anchors — prefer a pair with no edge yet,
     nearest row neighbors first */
  var existing = {};
  (Array.isArray(got.d.edges) ? got.d.edges : []).forEach(function(e){
    if (e) existing[e.from + '->' + e.to] = true;
  });
  var from = ids[0], to = ids[1];
  outer:
  for (var gap = 1; gap < ids.length; gap++){
    for (var i = 0; i + gap < ids.length; i++){
      if (!existing[ids[i] + '->' + ids[i + gap]]){
        from = ids[i]; to = ids[i + gap];
        break outer;
      }
      if (!existing[ids[i + gap] + '->' + ids[i]]){
        from = ids[i + gap]; to = ids[i];
        break outer;
      }
    }
  }
  var item = '{"from": ' + JSON.stringify(from) + ', "to": ' + JSON.stringify(to) +
             ', "kind": "int", "label": "describe the hop"}';
  var r = jsonInsertListItemOrCreate(text, got.path, 'edges', item);
  if (!r) return {error: 'could not edit edges in the editor text'};
  return {text: r.text, start: r.start, end: r.end, kind: 'edge',
          index: Array.isArray(got.d.edges) ? got.d.edges.length : 0};
}
function planAddStep(text, raw, sectionIdx, pathId){
  var got = builderDiagram(text, raw, sectionIdx);
  if (got.error) return got;
  if (got.d.paths) return planPathStepEdit(text,raw,sectionIdx,pathId,-1,'add');
  var edges = Array.isArray(got.d.edges) ? got.d.edges : [];
  /* prefer an edge no step uses as its FIRST hop, so the new numbered coin
     gets its own midpoint (two steps sharing a first hop stack coins) */
  var used = {};
  (got.d.steps || []).forEach(function(st){
    var k = st && (st.edge || (Array.isArray(st.edges) && st.edges[0]));
    if (typeof k === 'string') used[k] = true;
  });
  var pick = null;
  for (var i = 0; i < edges.length; i++){
    var e = edges[i] || {};
    var k = e.from + '->' + e.to;
    if (!used[k]){ pick = k; break; }
  }
  if (!pick && edges.length) pick = (edges[0] || {}).from + '->' + (edges[0] || {}).to;
  var item = JSON.stringify(Object.assign(pick ? {edge:pick} : {}, {text:'Describe what happens in this step'}));
  var r = jsonInsertListItemOrCreate(text, got.path, 'steps', item);
  if (!r) return {error: 'could not edit steps in the editor text'};
  return {text: r.text, start: r.start, end: r.end, kind: 'step',
          index: (got.d.steps || []).length};
}
function planAddPanel(text, raw, sectionIdx, type){
  /* type (optional): a PANEL_TEMPLATES key; default queue */
  var got = builderDiagram(text, raw, sectionIdx);
  if (got.error) return got;
  var tplKey = type && PANEL_TEMPLATES[type] ? type : 'queue';
  var taken = Object.create(null);
  (got.d.panels || []).forEach(function(p){ if (p && p.id) taken[p.id] = true; });
  var id = builderUniqueKey(taken, tplKey);
  var tpl = builderClone(PANEL_TEMPLATES[tplKey]);
  var entry = {id: id, type: tplKey};
  Object.keys(tpl).forEach(function(k){ entry[k] = tpl[k]; });
  var r = jsonInsertListItemOrCreate(text, got.path, 'panels', JSON.stringify(entry, null, 2));
  if (!r) return {error: 'could not edit panels in the editor text'};
  return {text: r.text, start: r.start, end: r.end, kind: 'panel',
          index: (got.d.panels || []).length};
}
var BUILDER_SECTION_TEMPLATE = [
  '{',
  '  "heading": "New section",',
  '  "accent": "cyan",',
  '  "text": ["What this flow does, in one or two sentences."],',
  '  "diagram": {',
  '    "nodes": {',
  '      "svc1": {"title": "Service A", "sub": "does a thing", "icon": "gear", "tint": "cmd"},',
  '      "svc2": {"title": "Service B", "sub": "stores it", "icon": "db", "tint": "data"}',
  '    },',
  '    "rows": [["svc1", "svc2"]],',
  '    "edges": [{"from": "svc1", "to": "svc2", "kind": "int", "label": "call"}],',
  '    "steps": [{"edge": "svc1->svc2", "text": "Service A calls Service B"}]',
  '  }',
  '}'
].join('\n');
function planAddSection(text, raw){
  var base, page;
  if (raw && raw.page){ page = raw.page; base = ['page']; }
  else if (raw && (raw.blocks || raw.sections)){ page = raw; base = []; }
  else if (raw && raw.nodes && raw.rows)
    return {error: 'this spec is a bare diagram — wrap it as {"page": {"blocks": [ {...} ]}} to hold more than one section'};
  else return {error: 'no page to add a section to'};
  var key = page.blocks ? 'blocks' : 'sections';
  if (!jsonLocate(text, base.concat([key])))
    return {error: 'could not find the ' + key + ' list in the editor text'};
  var r = jsonInsertMember(text, base.concat([key]), null, BUILDER_SECTION_TEMPLATE);
  if (!r) return {error: 'could not edit the ' + key + ' list in the editor text'};
  return {text: r.text, start: r.start, end: r.end, kind: 'section',
          index: specSectionPaths(raw).length};
}

/* ---------------- field edits, renames, deletes, reorders ----------------
   Two edit strategies. Single-field edits are SURGICAL: replace, insert, or
   remove one member's text and leave the rest of the document byte-for-byte
   untouched. Edits that must stay consistent across several diagram keys
   (renaming a node id, deleting a node, retargeting an edge) REWRITE one
   value — usually the section's diagram object — from a mutated copy,
   serialized with two-space indents and re-indented to the container
   depth. */

function jsonReplaceValue(text, path, valueText){
  /* Replace the value at path; multi-line valueText is re-indented to the
     member's line indent. Returns {text, start, end} or null. */
  var loc = jsonLocate(text, path);
  if (!loc) return null;
  var ls = text.lastIndexOf('\n', loc.keyStart) + 1;
  var indent = (text.slice(ls, loc.keyStart).match(/^[ \t]*/) || [''])[0];
  var adj = valueText.split('\n').join('\n' + indent);
  return {text: text.slice(0, loc.start) + adj + text.slice(loc.end),
          start: loc.start, end: loc.start + adj.length};
}
function jsonRemoveMember(text, containerPath, key){
  /* Remove one member (and the comma that binds it) from the object or
     array at containerPath. Returns {text} or null when absent. */
  var loc = containerPath.length ? jsonLocate(text, containerPath) : {start: jsonSkipWS(text, 0)};
  var cont = loc ? jsonContainer(text, loc.start) : null;
  if (!cont) return null;
  var idx = -1;
  for (var m = 0; m < cont.members.length; m++){
    if (cont.members[m].key === key){ idx = m; break; }
  }
  if (idx < 0) return null;
  var mem = cont.members[idx], from, to;
  if (cont.members.length === 1){ from = cont.open + 1; to = cont.close; }
  else if (idx === cont.members.length - 1){ from = cont.members[idx - 1].valEnd; to = mem.valEnd; }
  else { from = mem.keyStart; to = cont.members[idx + 1].keyStart; }
  return {text: text.slice(0, from) + text.slice(to)};
}
function jsonSetField(text, objPath, key, valueTextOrNull){
  /* Set (replace or insert) one field of the object at objPath; null value
     removes the field. Returns {text, start?, end?} or null. */
  var exists = jsonLocate(text, objPath.concat([key]));
  if (valueTextOrNull == null){
    if (!exists) return {text: text};
    return jsonRemoveMember(text, objPath, key);
  }
  if (exists) return jsonReplaceValue(text, objPath.concat([key]), valueTextOrNull);
  return jsonInsertMember(text, objPath, key, valueTextOrNull);
}

function builderClone(v){ return JSON.parse(JSON.stringify(v)); }
function builderRewrite(text, raw, path, mutate){
  /* Rewrite the value at path from a mutated deep copy. mutate(copy) edits
     in place and may return {error}. */
  var cur = specValueAt(raw, path);
  if (cur == null || typeof cur !== 'object')
    return {error: 'element not found in the editor text (click Render, then reselect)'};
  var copy = builderClone(cur);
  var out = mutate(copy);
  if (out && out.error) return out;
  var r = jsonReplaceValue(text, path, JSON.stringify(copy, null, 2));
  if (!r) return {error: 'could not rewrite the editor text'};
  return r;
}

function planSetField(text, raw, targetPath, key, valueTextOrNull){
  /* Surgical single-field edit on the object at targetPath. */
  if (!jsonLocate(text, targetPath))
    return {error: 'element not found in the editor text (click Render, then reselect)'};
  var r = jsonSetField(text, targetPath, key, valueTextOrNull);
  if (!r) return {error: 'could not edit the editor text'};
  return r;
}

function builderGroupsShapeError(d){
  /* the validator treats a non-object diagram.groups as "no declarations";
     every mutation planner refuses that shape outright — numeric own keys
     on strings and arrays would otherwise slip past hasOwnProperty checks
     and get object-coerced, corrupting the author's value */
  if (d.groups != null && (typeof d.groups !== 'object' || Array.isArray(d.groups)))
    return {error: 'diagram.groups is not an object — fix it in the JSON first'};
  return null;
}

function planSetNodeGroup(text, raw, sectionIdx, nodeId, keyOrNull){
  var got = builderDiagram(text, raw, sectionIdx);
  if (got.error) return got;
  var shape = builderGroupsShapeError(got.d);
  if (shape) return shape;
  if (!got.d.nodes || !Object.prototype.hasOwnProperty.call(got.d.nodes, nodeId))
    return {error: 'node "' + nodeId + '" not found'};
  if (keyOrNull != null && typeof keyOrNull !== 'string') return {error: 'group key must be text'};
  var key = keyOrNull == null ? null : keyOrNull.trim() || null;
  var plan = planSetField(text, raw, got.path.concat(['nodes', nodeId]), 'group',
                          key == null ? null : JSON.stringify(key));
  if (plan.error || key == null) return plan;
  var groups = got.d.groups;
  if (groups && Object.prototype.hasOwnProperty.call(groups, key)) return plan;
  var r = groups ? jsonSetField(plan.text, got.path.concat(['groups']), key, '{}')
                 : jsonSetField(plan.text, got.path, 'groups', '{' + JSON.stringify(key) + ': {}}');
  return r || {error: 'could not declare group'};
}

function planBulkSetGroup(text, raw, targets, keyOrNull){
  var cur = text;
  for (var i = 0; i < targets.length; i++){
    try { raw = JSON.parse(cur); }
    catch (ex){ return {error: 'bulk stopped: the JSON no longer parses (' + ex.message + ')'}; }
    var t = targets[i];
    if (t.kind !== 'node') return {error: 'groups can only contain nodes'};
    var plan = planSetNodeGroup(cur, raw, t.section, t.id, keyOrNull);
    if (plan.error) return {error: 'selection ' + (i + 1) + ': ' + plan.error};
    cur = plan.text;
  }
  return {text: cur, count: targets.length};
}

function planSetGroupTitle(text, raw, sectionIdx, key, titleOrNull){
  var got = builderDiagram(text, raw, sectionIdx);
  if (got.error) return got;
  if (typeof key !== 'string' || !key.trim()) return {error: 'a group needs a key'};
  var shape = builderGroupsShapeError(got.d);
  if (shape) return shape;
  return builderRewrite(text, raw, got.path, function(d){
    var groups = Object.assign(Object.create(null), d.groups || {});
    var meta = Object.assign(Object.create(null), groups[key] || {});
    if (titleOrNull == null || titleOrNull.trim() === '') delete meta.title;
    else meta.title = titleOrNull.trim();
    groups[key] = meta;
    d.groups = groups;
  });
}

function planSetGroupIcon(text, raw, sectionIdx, key, iconOrNull){
  var got = builderDiagram(text, raw, sectionIdx);
  if (got.error) return got;
  if (typeof key !== 'string' || !key.trim()) return {error: 'a group needs a key'};
  var shape = builderGroupsShapeError(got.d);
  if (shape) return shape;
  return builderRewrite(text, raw, got.path, function(d){
    var groups = Object.assign(Object.create(null), d.groups || {});
    var meta = Object.assign(Object.create(null), groups[key] || {});
    if (iconOrNull == null || iconOrNull.trim() === '') delete meta.icon;
    else meta.icon = iconOrNull.trim();
    groups[key] = meta;
    d.groups = groups;
  });
}

function planSetGroupParent(text, raw, sectionIdx, key, parentOrNull){
  var got = builderDiagram(text, raw, sectionIdx);
  if (got.error) return got;
  if (typeof key !== 'string' || !key.trim()) return {error: 'a group needs a key'};
  var shape = builderGroupsShapeError(got.d);
  if (shape) return shape;
  if (parentOrNull != null && typeof parentOrNull !== 'string') return {error: 'parent must be text'};
  return builderRewrite(text, raw, got.path, function(d){
    var groups = Object.assign(Object.create(null), d.groups || {});
    var meta = Object.assign(Object.create(null), groups[key] || {});
    if (parentOrNull == null || parentOrNull.trim() === '') delete meta.parent;
    else meta.parent = parentOrNull.trim();
    groups[key] = meta;
    d.groups = groups;
  });
}

function builderGroupParentOptions(groups, key){
  var parents = sanitizedGroupParents(groups);
  return Object.keys(groups || {}).filter(function(candidate){
    var cursor = candidate;
    while (cursor !== undefined){
      if (cursor === key) return false;
      cursor = parents[cursor];
    }
    return true;
  });
}

function planRenameGroup(text, raw, sectionIdx, oldKey, newKey){
  var got = builderDiagram(text, raw, sectionIdx);
  if (got.error) return got;
  var shape = builderGroupsShapeError(got.d);
  if (shape) return shape;
  if (typeof newKey !== 'string' || !newKey.trim()) return {error: 'a group needs a key'};
  newKey = newKey.trim();
  if (newKey === oldKey) return {error: 'same key'};
  var groups = got.d.groups || {}, nodes = got.d.nodes || {};
  var declared = Object.prototype.hasOwnProperty.call(groups, oldKey);
  var members = Object.keys(nodes).filter(function(id){ return nodes[id] && nodes[id].group === oldKey; });
  if (!declared && !members.length) return {error: 'group "' + oldKey + '" not found'};
  if (Object.prototype.hasOwnProperty.call(groups, newKey) || Object.keys(nodes).some(function(id){
    return nodes[id] && nodes[id].group === newKey;
  })) return {error: 'group "' + newKey + '" is already taken'};
  return builderRewrite(text, raw, got.path, function(d){
    members.forEach(function(id){ d.nodes[id].group = newKey; });
    if (declared){
      var renamed = Object.create(null);
      Object.keys(d.groups).forEach(function(k){ renamed[k === oldKey ? newKey : k] = d.groups[k]; });
      /* children nested under the old key must follow the rename, or their
         parent link dangles and the boxes silently flatten */
      Object.keys(renamed).forEach(function(k){
        if (renamed[k] && renamed[k].parent === oldKey) renamed[k].parent = newKey;
      });
      d.groups = renamed;
    }
  });
}

function planDeleteGroup(text, raw, sectionIdx, key){
  var got = builderDiagram(text, raw, sectionIdx);
  if (got.error) return got;
  var shape = builderGroupsShapeError(got.d);
  if (shape) return shape;
  return builderRewrite(text, raw, got.path, function(d){
    /* promote through the SANITIZED links: a dangling, self, or cyclic
       parent on the deleted group must not be handed down to children */
    var promoted = sanitizedGroupParents(d.groups)[key];
    if (d.groups) delete d.groups[key];
    /* children of the deleted group climb one level: they take its parent,
       or become top-level when it had none */
    Object.keys(d.groups || {}).forEach(function(k){
      if (!d.groups[k] || d.groups[k].parent !== key) return;
      if (typeof promoted === 'string') d.groups[k].parent = promoted;
      else delete d.groups[k].parent;
    });
    Object.keys(d.nodes || {}).forEach(function(id){
      if (d.nodes[id] && d.nodes[id].group === key) delete d.nodes[id].group;
    });
  });
}

function builderEdgeKey(e){ return ((e && e.from) || '') + '->' + ((e && e.to) || ''); }
function builderRetargetStepKeys(steps, oldKey, newKey){
  /* Point every step reference at newKey; null newKey removes the
     reference (a step may legally end up edgeless). */
  (steps || []).forEach(function(st){
    if (!st) return;
    if (st.edge === oldKey){
      if (newKey) st.edge = newKey; else delete st.edge;
    }
    if (Array.isArray(st.edges)){
      st.edges = st.edges.map(function(k){ return k === oldKey ? newKey : k; })
                         .filter(function(k){ return typeof k === 'string'; });
      if (!st.edges.length) delete st.edges;
    }
    if (st.failures && typeof st.failures === 'object' && !Array.isArray(st.failures)){
      var failures = Object.create(null);
      Object.keys(st.failures).forEach(function(key){
        var next = key === oldKey ? newKey : key;
        if (next) failures[next] = st.failures[key];
      });
      if (Object.keys(failures).length) st.failures = failures; else delete st.failures;
    }
  });
}

var BUILDER_ID_RE = /^[A-Za-z0-9_-]+$/;

function planSetEdgeEndpoint(text, raw, sectionIdx, edgeIdx, field, nodeId){
  /* Change an edge's from/to and retarget every step reference to the
     edge's old "from->to" key. */
  var got = builderDiagram(text, raw, sectionIdx);
  if (got.error) return got;
  var e = (got.d.edges || [])[edgeIdx];
  if (!e) return {error: 'edge not found — reselect and try again'};
  if (!got.d.nodes || !Object.prototype.hasOwnProperty.call(got.d.nodes, nodeId))
    return {error: 'unknown node id "' + nodeId + '"'};
  var oldKey = builderEdgeKey(e);
  return builderRewrite(text, raw, got.path, function(d){
    d.edges[edgeIdx][field] = nodeId;
    builderRetargetStepKeys(d.steps, oldKey, builderEdgeKey(d.edges[edgeIdx]));
  });
}

function planRenameNode(text, raw, sectionIdx, oldId, newId){
  /* Rename a node id everywhere it is referenced: the nodes map, rows and
     stacks, floats, edge endpoints, step node lists, and the step
     "from->to" keys of every edge whose endpoint changed. */
  var got = builderDiagram(text, raw, sectionIdx);
  if (got.error) return got;
  if (!BUILDER_ID_RE.test(newId || ''))
    return {error: 'node ids use letters, digits, _ and - only'};
  if (!got.d.nodes || !Object.prototype.hasOwnProperty.call(got.d.nodes, oldId))
    return {error: 'node "' + oldId + '" not found'};
  if (newId === oldId) return {error: 'same id'};
  if (Object.prototype.hasOwnProperty.call(got.d.nodes, newId))
    return {error: 'id "' + newId + '" is already taken'};
  return builderRewrite(text, raw, got.path, function(d){
    /* null-prototype map: a plain {} would route an id like "__proto__"
       through the prototype setter and silently drop the node */
    var nodes = Object.create(null);
    Object.keys(d.nodes).forEach(function(k){ nodes[k === oldId ? newId : k] = d.nodes[k]; });
    d.nodes = nodes;
    d.rows = (d.rows || []).map(function(row){
      return row.map(function(slot){
        if (Array.isArray(slot)) return slot.map(function(s){ return s === oldId ? newId : s; });
        return slot === oldId ? newId : slot;
      });
    });
    (Array.isArray(d.floats) ? d.floats : []).forEach(function(f){
      if (f && f.id === oldId) f.id = newId;
    });
    var renamedKeys = [];
    (d.edges || []).forEach(function(e){
      if (!e) return;
      var was = builderEdgeKey(e), hit = false;
      if (e.from === oldId){ e.from = newId; hit = true; }
      if (e.to === oldId){ e.to = newId; hit = true; }
      if (hit) renamedKeys.push([was, builderEdgeKey(e)]);
    });
    (d.steps || []).forEach(function(st){
      if (st && Array.isArray(st.nodes))
        st.nodes = st.nodes.map(function(n){ return n === oldId ? newId : n; });
    });
    renamedKeys.forEach(function(pair){ builderRetargetStepKeys(d.steps, pair[0], pair[1]); });
  });
}

function planRenamePanel(text, raw, sectionIdx, panelIdx, newId){
  /* Rename a panel id and move every step patch keyed by it. */
  var got = builderDiagram(text, raw, sectionIdx);
  if (got.error) return got;
  var p = (got.d.panels || [])[panelIdx];
  if (!p) return {error: 'panel not found — reselect and try again'};
  if (!BUILDER_ID_RE.test(newId || ''))
    return {error: 'panel ids use letters, digits, _ and - only'};
  var oldId = p.id;
  if (newId === oldId) return {error: 'same id'};
  if ((got.d.panels || []).some(function(q){ return q && q.id === newId; }))
    return {error: 'id "' + newId + '" is already taken'};
  return builderRewrite(text, raw, got.path, function(d){
    d.panels[panelIdx].id = newId;
    if (d.primaryPanel === oldId) d.primaryPanel = newId;
    if(d.sectionLayout)Object.keys(d.sectionLayout).forEach(function(target){
      if(Array.isArray(d.sectionLayout[target]))d.sectionLayout[target].forEach(function(it){if(it && it.panel===oldId)it.panel=newId;});
    });
    (d.steps || []).forEach(function(st){
      if (st && st.panels && Object.prototype.hasOwnProperty.call(st.panels, oldId)){
        var patches = Object.create(null); /* "__proto__" — see planRenameNode */
        Object.keys(st.panels).forEach(function(k){ patches[k === oldId ? newId : k] = st.panels[k]; });
        st.panels = patches;
      }
    });
  });
}

function planDeleteNode(text, raw, sectionIdx, id){
  /* Remove a node plus its row/float placement and every edge touching it;
     step references to the removed edges and the node are pruned (a step
     may legally stay as caption-only). */
  var got = builderDiagram(text, raw, sectionIdx);
  if (got.error) return got;
  if (!got.d.nodes || !Object.prototype.hasOwnProperty.call(got.d.nodes, id))
    return {error: 'node "' + id + '" not found'};
  return builderRewrite(text, raw, got.path, function(d){
    delete d.nodes[id];
    d.rows = (d.rows || []).map(function(row){
      return row.map(function(slot){
        return Array.isArray(slot) ? slot.filter(function(s){ return s !== id; }) : slot;
      }).filter(function(slot){
        return Array.isArray(slot) ? slot.length > 0 : slot !== id;
      });
    }).filter(function(row){ return row.length > 0; });
    if (Array.isArray(d.floats)){
      d.floats = d.floats.filter(function(f){ return !(f && f.id === id); });
      if (!d.floats.length) delete d.floats;
    }
    var removedKeys = [];
    if (Array.isArray(d.edges)){
      d.edges = d.edges.filter(function(e){
        var hit = e && (e.from === id || e.to === id);
        if (hit) removedKeys.push(builderEdgeKey(e));
        return !hit;
      });
    }
    var surviving = {};
    (d.edges || []).forEach(function(e){ if (e) surviving[builderEdgeKey(e)] = true; });
    removedKeys.forEach(function(k){
      if (!surviving[k]) builderRetargetStepKeys(d.steps, k, null);
    });
    (d.steps || []).forEach(function(st){
      if (st && Array.isArray(st.nodes)){
        st.nodes = st.nodes.filter(function(n){ return n !== id; });
        if (!st.nodes.length) delete st.nodes;
      }
    });
  });
}

function planDeleteEdge(text, raw, sectionIdx, edgeIdx){
  var got = builderDiagram(text, raw, sectionIdx);
  if (got.error) return got;
  var e = (got.d.edges || [])[edgeIdx];
  if (!e) return {error: 'edge not found — reselect and try again'};
  var key = builderEdgeKey(e);
  return builderRewrite(text, raw, got.path, function(d){
    d.edges.splice(edgeIdx, 1);
    var stillThere = d.edges.some(function(o){ return o && builderEdgeKey(o) === key; });
    if (!stillThere) builderRetargetStepKeys(d.steps, key, null);
  });
}

function planDeletePanel(text, raw, sectionIdx, panelIdx){
  var got = builderDiagram(text, raw, sectionIdx);
  if (got.error) return got;
  var p = (got.d.panels || [])[panelIdx];
  if (!p) return {error: 'panel not found — reselect and try again'};
  var id = p.id;
  return builderRewrite(text, raw, got.path, function(d){
    if (d.primaryPanel === id) delete d.primaryPanel;
    if(d.sectionLayout)Object.keys(d.sectionLayout).forEach(function(target){
      if(Array.isArray(d.sectionLayout[target]))d.sectionLayout[target]=d.sectionLayout[target].filter(function(it){return !it || it.panel!==id;});
    });
    d.panels.splice(panelIdx, 1);
    if (!d.panels.length) delete d.panels;
    (d.steps || []).forEach(function(st){
      if (st && st.panels && Object.prototype.hasOwnProperty.call(st.panels, id)){
        delete st.panels[id];
        if (!Object.keys(st.panels).length) delete st.panels;
      }
    });
  });
}

function planDeleteStep(text, raw, sectionIdx, stepIdx){
  var got = builderDiagram(text, raw, sectionIdx);
  if (got.error) return got;
  if (!Array.isArray(got.d.steps) || !got.d.steps[stepIdx])
    return {error: 'step not found — reselect and try again'};
  if (got.d.paths){
    var id = got.d.steps[stepIdx].id;
    if (got.d.paths.some(function(p){return p.steps.length === 1 && p.steps[0] === id;}))
      return {error:'This is the only step in a path. Remove that path or add another step first.'};
    return builderRewrite(text,raw,got.path,function(d){
      d.steps.splice(stepIdx,1);
      d.paths.forEach(function(p){p.steps=p.steps.filter(function(ref){return ref !== id;});});
    });
  }
  return builderRewrite(text, raw, got.path.concat(['steps']), function(steps){
    steps.splice(stepIdx, 1);
  });
}

function planMoveStep(text, raw, sectionIdx, stepIdx, delta, pathId){
  var got = builderDiagram(text, raw, sectionIdx);
  if (got.error) return got;
  if (got.d.paths) return planPathStepEdit(text,raw,sectionIdx,pathId,stepIdx,delta < 0 ? 'earlier' : 'later');
  var steps = got.d.steps;
  var to = stepIdx + delta;
  if (!Array.isArray(steps) || !steps[stepIdx]) return {error: 'step not found'};
  if (to < 0 || to >= steps.length) return {error: 'already at that end'};
  var r = builderRewrite(text, raw, got.path.concat(['steps']), function(copy){
    var item = copy.splice(stepIdx, 1)[0];
    copy.splice(to, 0, item);
  });
  if (r.error) return r;
  r.index = to;
  return r;
}

function planDuplicateStep(text, raw, sectionIdx, stepIdx, pathId){
  var got = builderDiagram(text, raw, sectionIdx);
  if (got.error) return got;
  if (got.d.paths) return planPathStepEdit(text,raw,sectionIdx,pathId,stepIdx,'duplicate');
  var steps = got.d.steps;
  if (!Number.isInteger(stepIdx) || !Array.isArray(steps) || !steps[stepIdx]) return {error:'step not found'};
  var clone = builderClone(steps[stepIdx]);
  if (typeof clone.id === 'string' && clone.id){
    var taken = Object.create(null);
    steps.forEach(function(step){ if (step && typeof step.id === 'string') taken[step.id] = true; });
    clone.id = builderUniqueKey(taken, clone.id + '-copy');
  }
  var r = jsonInsertArrayItemAfter(text, got.path.concat(['steps']), stepIdx, JSON.stringify(clone, null, 2));
  if (!r) return {error:'could not edit steps in the editor text'};
  return {text:r.text, start:r.start, end:r.end, kind:'step', index:stepIdx + 1};
}

/* Path edits change references; shared step bodies remain in one registry. */
function planPathStepEdit(text,raw,section,pathId,index,action,metadata){
  var got = builderDiagram(text,raw,section);
  if (got.error) return got;
  var resultIndex=index, resultPath=pathId;
  var r=builderRewrite(text,raw,got.path,function(d){
    var steps=d.steps || [], taken=Object.create(null);
    steps.forEach(function(s){if(s && s.id) taken[s.id]=true;});
    function newId(stem){var id=builderUniqueKey(taken,stem);taken[id]=true;return id;}
    if (!d.paths){
      if (action !== 'fork') return {error:'No alternate paths yet.'};
      if (!steps.length || !steps[index]) return {error:'Select a step to branch from first.'};
      steps.forEach(function(s){if(!s.id) s.id=newId('step-');});
      d.paths=[{id:'happy',label:'Happy path',color:'#38bdf8',steps:steps.map(function(s){return s.id;})}];
    }
    var p=d.paths.find(function(p){return p.id === pathId;}) || (!pathId ? d.paths[0] : null);
    if(!p) return {error:'Path no longer exists. Select it again.'};
    var at=steps[index] ? p.steps.indexOf(steps[index].id) : -1;
    if (['fork','duplicate','earlier','later'].indexOf(action)>=0 && at<0) return {error:'Select a step in this path first.'};
    resultPath=p.id;
    if(action === 'fork'){
      var pathIds=Object.create(null);d.paths.forEach(function(p){pathIds[p.id]=true;});
      var id=builderUniqueKey(pathIds,'alternate-');
      var step={id:newId('outcome-'),text:'Describe what happens on this alternate path',nodes:Object.keys(d.nodes || {}).slice(0,1)};
      resultIndex=steps.length;steps.push(step);resultPath=id;
      d.paths.push({id:id,label:d.paths.length===1?'Dropped signal':'Alternate path '+d.paths.length,
        color:['#fb923c','#c084fc','#f472b6','#4ade80'][(d.paths.length-1)%4],steps:p.steps.slice(0,at+1).concat(step.id)});
    } else if(action === 'add' || action === 'duplicate'){
      var step=action==='duplicate'?builderClone(steps[index]):{text:'Describe what happens in this step',nodes:Object.keys(d.nodes || {}).slice(0,1)};
      step.id=newId(action==='duplicate'?step.id+'-copy':'step-');resultIndex=steps.length;steps.push(step);
      p.steps.splice(action==='duplicate'?at+1:p.steps.length,0,step.id);
    } else if(action === 'earlier' || action === 'later'){
      var to=at+(action==='earlier'?-1:1);
      if(to<0 || to>=p.steps.length) return {error:'Already at that end of this path.'};
      p.steps.splice(to,0,p.steps.splice(at,1)[0]);
    } else if(action === 'metadata'){
      if(!metadata || typeof metadata.label!=='string' || !metadata.label.trim() || !isHex(metadata.color))
        return {error:'Give the path a label and a hex color.'};
      p.label=metadata.label.trim();p.color=metadata.color;
      if(at<0) resultIndex=steps.findIndex(function(s){return s.id===p.steps[0];});
    } else if(action === 'remove'){
      if(d.paths.length<2 || d.paths[0]===p) return {error:'Keep the primary path; remove an alternate instead.'};
      d.paths=d.paths.filter(function(other){return other!==p;});resultPath=d.paths[0].id;
      resultIndex=steps.findIndex(function(s){return s.id===d.paths[0].steps[0];});
    } else return {error:'Unknown path edit.'};
    var errors=[];validatePaths(d,'diagram',errors);
    if(errors.length) return {error:errors.join('\n')};
  });
  if(r.error) return r;
  r.kind='step';r.index=resultIndex;r.pathId=resultPath;
  var range=jsonLocate(r.text,got.path.concat(['steps',resultIndex]));
  if(range){r.start=range.start;r.end=range.end;}
  return r;
}

function planMoveRow(text, raw, sectionIdx, fromIdx, toIdx){
  /* lift one layout row out of diagram.rows and re-insert it at toIdx
     (index AFTER removal — the drop code converts gap positions) */
  var got = builderDiagram(text, raw, sectionIdx);
  if (got.error) return got;
  var rows = got.d.rows;
  if (!Array.isArray(rows) || !rows[fromIdx]) return {error: 'row not found'};
  if (toIdx < 0 || toIdx >= rows.length) return {error: 'no row slot there'};
  if (toIdx === fromIdx) return {error: 'already there'};
  var r = builderRewrite(text, raw, got.path.concat(['rows']), function(copy){
    var item = copy.splice(fromIdx, 1)[0];
    copy.splice(toIdx, 0, item);
  });
  if (r.error) return r;
  r.index = toIdx;
  return r;
}

function planMoveGroup(text, raw, sectionIdx, groupKey, drop){
  var got = builderDiagram(text, raw, sectionIdx);
  if (got.error) return got;
  var nodes = got.d.nodes || {}, members = Object.create(null);
  Object.keys(nodes).forEach(function(id){
    if (nodes[id] && nodes[id].group === groupKey) members[id] = true;
  });
  if (!Object.keys(members).length) return {error: 'group "' + groupKey + '" not found'};
  var rows = got.d.rows;
  if (!builderFlatRowIds(rows).some(function(id){ return members[id]; }))
    return {error: 'group "' + groupKey + '" has no nodes placed in rows'};
  return builderRewrite(text, raw, got.path.concat(['rows']), function(copy){
    return builderLiftAndInsert(copy, members, drop);
  });
}

function builderLiftAndInsert(copy, members, drop, opts){
  /* Shared pre-removal lift/insert rules for groups and individual nodes.
     Floating nodes supply a run; float membership can request only a lift. */
  opts = opts || {};
  var rows = copy, before = JSON.stringify(copy);
  var inRow = drop && Object.prototype.hasOwnProperty.call(drop, 'row');
  if (!opts.liftOnly && (!drop || (inRow ? (!Number.isInteger(drop.row) || !rows[drop.row] || !Number.isInteger(drop.slot)) :
      (!Number.isInteger(drop.gap) || drop.gap < 0 || drop.gap > rows.length))))
    return {error: 'no row slot there'};
  var run = (opts.run || []).slice(), kept = [], target = null, droppedAbove = 0, removedBeforeSlot = 0;
  copy.forEach(function(row, r){
    var remaining = [];
    row.forEach(function(slot, si){
      var consumed = false;
      if (!Array.isArray(slot)){
        if (members[slot]){ run.push(slot); consumed = true; }
        else remaining.push(slot);
      } else {
        var extracted = slot.filter(function(id){ return members[id]; });
        if (!extracted.length) remaining.push(slot);
        else if (extracted.length === slot.length){ run.push(opts.plainStacks && slot.length === 1 ? slot[0] : slot); consumed = true; }
        else {
          var leftover = slot.filter(function(id){ return !members[id]; });
          remaining.push(leftover.length === 1 ? leftover[0] : leftover);
          extracted.forEach(function(id){ run.push(id); });
        }
      }
      /* drop.slot is a PRE-removal index: slots fully lifted into the
         run before it no longer occupy a position (a partial stack
         still does — its leftover stays behind) */
      if (consumed && inRow && r === drop.row && si < drop.slot) removedBeforeSlot++;
    });
    if (remaining.length){
      kept.push(remaining);
      if (inRow && r === drop.row) target = remaining;
    } else if (!opts.liftOnly && !inRow && r < drop.gap) droppedAbove++;
  });
  if (opts.liftOnly){
    /* The caller checked that at least one placed id survives. */
    if (!kept.length) return {error: 'the last node in rows cannot float'};
  } else if (inRow){
    /* Keep the pre-removal row's identity, convert the slot to the
       surviving row's indexing, then clamp. A wholly lifted target row
       is a no-op. */
    if (!target) return {error: 'already there'};
    var slotIdx = Math.max(0, Math.min(drop.slot - removedBeforeSlot, target.length));
    run.forEach(function(slot, i){ target.splice(slotIdx + i, 0, slot); });
  } else kept.splice(drop.gap - droppedAbove, 0, run);
  if (JSON.stringify(kept) === before) return {error: 'already there'};
  copy.splice(0, copy.length);
  kept.forEach(function(row){ copy.push(row); });
}

function builderRemoveFloat(d, id){
  if (!Array.isArray(d.floats)) return;
  d.floats = d.floats.filter(function(f){ return !(f && f.id === id); });
  if (!d.floats.length) delete d.floats;
}

function planMoveNode(text, raw, sectionIdx, id, drop){
  var got = builderDiagram(text, raw, sectionIdx);
  if (got.error) return got;
  if (!got.d.nodes || !Object.prototype.hasOwnProperty.call(got.d.nodes, id))
    return {error: 'node "' + id + '" not found'};
  var inRows = builderFlatRowIds(got.d.rows).indexOf(id) >= 0;
  var floating = (got.d.floats || []).some(function(f){ return f && f.id === id; });
  if (!inRows && !floating) return {error: 'node "' + id + '" has no layout slot (rows or floats) to move'};
  if (!Array.isArray(got.d.rows) || !got.d.rows.length) return {error: 'no rows layout in this section'};
  var copy = builderClone(got.d.rows), members = Object.create(null);
  members[id] = true;
  var out = builderLiftAndInsert(copy, members, drop, {plainStacks: true, run: inRows ? [] : [id]});
  if (out && out.error) return out;
  var pairs = [['rows', JSON.stringify(copy)]];
  if (floating){
    var d = {floats: builderClone(got.d.floats)};
    builderRemoveFloat(d, id);
    pairs.push(['floats', d.floats ? JSON.stringify(d.floats) : null]);
  }
  return planSetFields(text, raw, got.path, pairs);
}

function planSetNodeFloat(text, raw, sectionIdx, id, sideOrNull){
  var got = builderDiagram(text, raw, sectionIdx);
  if (got.error) return got;
  if (!got.d.nodes || !Object.prototype.hasOwnProperty.call(got.d.nodes, id))
    return {error: 'node "' + id + '" not found'};
  var side = sideOrNull == null || sideOrNull === '' ? null : sideOrNull;
  if (side !== null && side !== 'above' && side !== 'below') return {error: 'float side must be above or below'};
  var ids = builderFlatRowIds(got.d.rows), inRows = ids.indexOf(id) >= 0;
  var floating = (got.d.floats || []).some(function(f){ return f && f.id === id; });
  if (!side && !floating) return {error: inRows ? 'already placed in rows' : 'node "' + id + '" has no float placement'};
  if (side && inRows && !ids.some(function(other){ return other !== id; }))
    return {error: 'the last node in rows cannot float'};
  if (!Array.isArray(got.d.rows) || !got.d.rows.length) return {error: 'no rows layout in this section'};
  return builderRewrite(text, raw, got.path, function(d){
    if (!side){
      builderRemoveFloat(d, id);
      /* a node malformed into BOTH rows and floats just loses the float
         entry — appending would duplicate its rows placement */
      if (!inRows) d.rows.push([id]);
      return;
    }
    if (inRows){
      var members = Object.create(null);
      members[id] = true;
      var out = builderLiftAndInsert(d.rows, members, null, {liftOnly: true});
      if (out && out.error) return out;
    }
    if (floating){
      d.floats.forEach(function(f){ if (f && f.id === id) f.side = side; });
    } else {
      if (!Array.isArray(d.floats)) d.floats = [];
      d.floats.push({id: id, side: side});
    }
  });
}

function builderSlotGapXs(boxes, reversed){
  /* Slot order follows the engine's serpentine rows, so "before" is on
     the right for a reversed row. Boxes already union stacked cards. */
  if (!boxes.length) return [];
  var xs = [reversed ? boxes[0].x2 + 8 : boxes[0].x1 - 8];
  for (var i = 1; i < boxes.length; i++)
    xs.push(reversed ? (boxes[i - 1].x1 + boxes[i].x2) / 2 : (boxes[i - 1].x2 + boxes[i].x1) / 2);
  xs.push(reversed ? boxes[boxes.length - 1].x1 - 8 : boxes[boxes.length - 1].x2 + 8);
  return xs;
}

function planDeleteSection(text, raw, sectionIdx){
  var rec = specSectionPaths(raw)[sectionIdx];
  if (!rec) return {error: 'no such section'};
  if (!rec.section.length)
    return {error: 'this spec is one bare diagram — clear the editor instead of deleting'};
  var parentPath = rec.section.slice(0, -1);
  var key = rec.section[rec.section.length - 1];
  var r = jsonRemoveMember(text, parentPath, key);
  if (!r) return {error: 'could not edit the editor text'};
  return r;
}

