/* ---------------- pass 3: direct-manipulation planners ---------------- */

function jsonInsertArrayItemAfter(text, arrPath, afterIdx, itemText){
  /* Insert itemText into the array at arrPath directly AFTER member
     afterIdx (jsonInsertMember only appends at the end). */
  var loc = arrPath.length ? jsonLocate(text, arrPath) : {start: jsonSkipWS(text, 0)};
  var cont = loc ? jsonContainer(text, loc.start) : null;
  if (!cont || cont.isObj) return null;
  var anchor = cont.members[afterIdx];
  if (!anchor) return null;
  var ls = text.lastIndexOf('\n', anchor.keyStart) + 1;
  var indent = (text.slice(ls, anchor.keyStart).match(/^[ \t]*/) || [''])[0];
  var adjVal = itemText.split('\n').join('\n' + indent);
  var prefix = ',\n' + indent;
  var insertAt = anchor.valEnd;
  var start = insertAt + prefix.length;
  return {text: text.slice(0, insertAt) + prefix + adjVal + text.slice(insertAt),
          start: start, end: start + adjVal.length};
}

function planReplaceValue(text, raw, path, valueText){
  /* Replace one whole value (a bullet string, a paragraph) in place. */
  if (!jsonLocate(text, path))
    return {error: 'element not found in the editor text (click Render, then reselect)'};
  var r = jsonReplaceValue(text, path, valueText);
  if (!r) return {error: 'could not edit the editor text'};
  return r;
}
function planSetFields(text, raw, targetPath, pairs){
  /* Several surgical field edits on one object under a single undo step
     (the label drag commits labelDx and labelDy together). */
  if (!jsonLocate(text, targetPath))
    return {error: 'element not found in the editor text (click Render, then reselect)'};
  var out = text;
  for (var i = 0; i < pairs.length; i++){
    var r = jsonSetField(out, targetPath, pairs[i][0], pairs[i][1]);
    if (!r) return {error: 'could not edit the editor text'};
    out = r.text;
  }
  return {text: out};
}
function planDeleteListItem(text, raw, containerPath, index){
  /* Remove one entry from a plain list (bullets, text paragraphs,
     contract fields). */
  if (!jsonLocate(text, containerPath))
    return {error: 'list not found in the editor text'};
  var r = jsonRemoveMember(text, containerPath, index);
  if (!r) return {error: 'no such entry'};
  return r;
}

function planAddEdgeBetween(text, raw, sectionIdx, fromId, toId){
  /* Connect mode: the operator clicked the exact source and target. */
  var got = builderDiagram(text, raw, sectionIdx);
  if (got.error) return got;
  var nodes = got.d.nodes || {};
  if (!Object.prototype.hasOwnProperty.call(nodes, fromId))
    return {error: 'unknown node id "' + fromId + '"'};
  if (!Object.prototype.hasOwnProperty.call(nodes, toId))
    return {error: 'unknown node id "' + toId + '"'};
  if (fromId === toId) return {error: 'source and target are the same node'};
  var key = fromId + '->' + toId;
  if ((got.d.edges || []).some(function(e){ return e && builderEdgeKey(e) === key; }))
    return {error: 'edge "' + key + '" already exists \u2014 click it to edit'};
  var item = '{"from": ' + JSON.stringify(fromId) + ', "to": ' + JSON.stringify(toId) +
             ', "kind": "int", "label": "describe the hop"}';
  var r = jsonInsertListItemOrCreate(text, got.path, 'edges', item);
  if (!r) return {error: 'could not edit edges in the editor text'};
  return {text: r.text, start: r.start, end: r.end, kind: 'edge',
          index: Array.isArray(got.d.edges) ? got.d.edges.length : 0};
}

function planDuplicateNode(text, raw, sectionIdx, id){
  /* Copy a node definition under a fresh id and place the copy right
     beside the original (same row slot, same stack, or floats list). */
  var got = builderDiagram(text, raw, sectionIdx);
  if (got.error) return got;
  var d = got.d;
  if (!d.nodes || !Object.prototype.hasOwnProperty.call(d.nodes, id))
    return {error: 'node "' + id + '" not found'};
  var newId = builderUniqueKey(d.nodes, id);
  var placed = null;
  (d.rows || []).forEach(function(row, r){
    if (placed) return;
    row.forEach(function(slot, s){
      if (placed) return;
      if (slot === id) placed = {path: got.path.concat(['rows', r]), after: s};
      else if (Array.isArray(slot)){
        var k = slot.indexOf(id);
        if (k >= 0) placed = {path: got.path.concat(['rows', r, s]), after: k};
      }
    });
  });
  var out;
  if (placed){
    out = jsonInsertArrayItemAfter(text, placed.path, placed.after, JSON.stringify(newId));
    if (!out) return {error: 'could not edit rows in the editor text'};
  } else {
    var floats = d.floats || [];
    var fi = -1;
    floats.forEach(function(f, i){ if (fi < 0 && f && f.id === id) fi = i; });
    if (fi < 0) return {error: 'node "' + id + '" has no row or float placement to copy'};
    /* clone the WHOLE float entry (side plus any nudge fields), fresh id,
       placed directly after the original like the row cases */
    var entry = builderClone(floats[fi]);
    entry.id = newId;
    out = jsonInsertArrayItemAfter(text, got.path.concat(['floats']), fi, JSON.stringify(entry));
    if (!out) return {error: 'could not edit floats in the editor text'};
  }
  var def = jsonInsertMember(out.text, got.path.concat(['nodes']), newId,
    JSON.stringify(builderClone(d.nodes[id])));
  if (!def) return {error: 'could not edit nodes in the editor text'};
  return {text: def.text, start: def.start, end: def.end, kind: 'node', id: newId};
}

function planDuplicateSection(text, raw, sectionIdx){
  /* Deep-copy a section directly after the original; the copy renders as
     the next section ordinal (render order is depth-first list order). */
  var rec = specSectionPaths(raw)[sectionIdx];
  if (!rec) return {error: 'no such section'};
  if (!rec.section.length)
    return {error: 'this spec is one bare diagram \u2014 wrap it as {"page": {"blocks": [ ... ]}} first'};
  var clone = builderClone(specValueAt(raw, rec.section));
  if (clone && typeof clone.heading === 'string') clone.heading += ' (copy)';
  var parentPath = rec.section.slice(0, -1);
  var idx = rec.section[rec.section.length - 1];
  var r = jsonInsertArrayItemAfter(text, parentPath, idx, JSON.stringify(clone, null, 2));
  if (!r) return {error: 'could not edit the editor text'};
  return {text: r.text, start: r.start, end: r.end, kind: 'section', index: sectionIdx + 1};
}

/* ---------------- durability: filenames ---------------- */

function specFileName(raw){
  /* download name for the save button: page-title slug + .spec.json */
  var page = raw && raw.page ? raw.page : raw;
  var title = page && typeof page.title === 'string' ? page.title : '';
  var slug = title.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '');
  return (slug || 'flowspec') + '.spec.json';
}

/* ---------------- hosted starter manifest ----------------
   A hosted workbench can ship a starters.json BESIDE the page and grow
   it over time without rebuilding: a top-level array (or
   {"starters": [...]}) of {name, spec} entries, desc optional. Invalid
   entries are skipped and counted so one typo never hides the rest. */

function parseStarterManifest(text){
  var data;
  try { data = JSON.parse(text); }
  catch (ex){ return {error: 'starters.json is not valid JSON (' + ex.message + ')'}; }
  var list = Array.isArray(data) ? data :
             (data && Array.isArray(data.starters) ? data.starters : null);
  if (!list) return {error: 'starters.json must be an array of {name, spec} entries (or {"starters": [...]})'};
  var entries = [], skipped = 0;
  list.forEach(function(e){
    var ok = e && typeof e.name === 'string' && e.name.trim() &&
             e.spec && typeof e.spec === 'object' && !Array.isArray(e.spec);
    if (ok) entries.push({name: e.name.trim(),
                          desc: typeof e.desc === 'string' ? e.desc : 'from starters.json',
                          spec: e.spec});
    else skipped++;
  });
  return {entries: entries, skipped: skipped};
}

/* ---------------- export: spec -> published page ----------------
   Client-side mirror of tools/inject.py: swap the template's one
   line-anchored flowspec JSON block for the editor text and retitle
   the page. Tag literals are concatenated so this file survives being
   inlined into a <script> block by the build. */

var FLOWSPEC_OPEN = '<scr' + 'ipt type="application/json" id="flowspec">';
var FLOWSPEC_CLOSE = '</scr' + 'ipt>';

function exportTemplateOpeners(templateText){
  /* line-anchored flowspec block openers (optional CR before the line
     end so CRLF templates count too) */
  var openRe = new RegExp('^' + FLOWSPEC_OPEN.replace(/[/\\^$.*+?()[\]{}|]/g, '\\$&') + '\\r?$', 'gm');
  return (templateText.match(openRe) || []).length;
}
function buildExportHtml(templateText, specText){
  /* the close-tag scan is case-insensitive — HTML tag names are, so
     "</SCRIPT" would break out of the JSON block just as surely */
  if (/<\/script/i.test(specText))
    return {error: 'the spec contains a literal "</scr' + 'ipt" — escape it as "<\\/scr' + 'ipt" first'};
  var spec;
  try { spec = JSON.parse(specText); }
  catch (ex){ return {error: 'not valid JSON (' + ex.message + ')'}; }
  var openRe = new RegExp('^' + FLOWSPEC_OPEN.replace(/[/\\^$.*+?()[\]{}|]/g, '\\$&') + '\\r?$', 'gm');
  var opens = templateText.match(openRe) || [];
  if (opens.length !== 1)
    return {error: 'the page template must hold exactly one flowspec block — found ' + opens.length};
  var start = templateText.search(openRe);
  var bodyFrom = start + FLOWSPEC_OPEN.length;
  var end = templateText.indexOf('\n' + FLOWSPEC_CLOSE, bodyFrom);
  if (end < 0) return {error: 'the page template’s flowspec block never closes'};
  var out = templateText.slice(0, bodyFrom) + '\n' + specText.trim() +
            templateText.slice(end);
  var page = spec && spec.page ? spec.page : spec;
  var title = page && typeof page.title === 'string' ? page.title : '';
  if (title){
    var safe = title.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
    out = out.replace(/<title>[\s\S]*?<\/title>/, '<title>' + safe + '</title>');
  }
  return {html: out};
}

/* ---------------- clickable validation findings ----------------
   Validator and lint messages open with a field path relative to the
   normalized PAGE object ("blocks[0].tabs[1].sections[0].diagram.
   edges[3].kind: ..."). These helpers turn that prefix back into a
   character range of the RAW editor text so a click on the message
   selects the offending JSON — falling back to the nearest existing
   parent when the exact leaf is not in the text. */

function parseValidationPath(message){
  /* leading "ERROR " / "warn " labels are tolerated; returns the path
     segment array or null when the message carries no field path */
  var input = (message || '').replace(/^(?:ERROR\s+|warn\s+)/, '');
  if (/^\(whole document\)\s*:/.test(input)) return [];
  var out = [], i = 0;
  while (i < input.length){
    var m;
    if (input[i] === '"'){
      var end = jsonSkipString(input, i);
      try { out.push(JSON.parse(input.slice(i, end))); } catch (ex){ return null; }
      i = end;
    } else {
      m = /^[A-Za-z0-9_$-]+/.exec(input.slice(i));
      if (!m || (!out.length && !/^[A-Za-z_]/.test(m[0]))) return null;
      out.push(m[0]); i += m[0].length;
    }
    while ((m = /^\[(\d+)\]/.exec(input.slice(i)))){
      out.push(parseInt(m[1], 10)); i += m[0].length;
    }
    if (/^\s*:/.test(input.slice(i))) return out;
    if (input[i] !== '.') return null;
    i++;
  }
  return null;
}
function findingLocation(text, raw, message, rawPath){
  /* character range for a validation message. The validator addresses
     the normalized PAGE object; a leading "page" token names that same
     object. Remaining tokens are resolved GREEDILY against the parsed
     raw JSON — at each object level the longest dot-join of remaining
     string tokens that names a real member wins, so author ids that
     contain dots still resolve. Unresolvable tails retreat to the
     nearest existing parent (exact: false). rawPath supplies an explicit
     editor path for diff findings, using the same locator and fallback. */
  var tokens = rawPath || parseValidationPath(message);
  if (!tokens) return null;
  if (!rawPath && tokens[0] === 'page') tokens = tokens.slice(1);
  var base, node;
  if (rawPath){ base = []; node = raw; }
  else if (raw && raw.page){ base = ['page']; node = raw.page; }
  else if (raw && (raw.blocks || raw.sections)){ base = []; node = raw; }
  else if (raw && raw.nodes && raw.rows){
    /* normalize() wrapped the bare diagram as sections[0].diagram */
    if (tokens.length >= 2 && tokens[0] === 'sections' && tokens[1] === 0){
      tokens = tokens.slice(2);
      if (tokens[0] === 'diagram') tokens = tokens.slice(1);
    } else if (tokens.length){
      return null; /* the message names page furniture a bare diagram lacks */
    }
    base = []; node = raw;
  } else return null;
  var path = base.slice();
  var i = 0;
  while (i < tokens.length && node != null && typeof node === 'object'){
    if (Array.isArray(node)){
      if (typeof tokens[i] !== 'number') break;
      path.push(tokens[i]);
      node = node[tokens[i]];
      i++;
    } else {
      var key = null, j;
      for (j = rawPath ? i + 1 : tokens.length; j > i; j--){
        var joined = tokens.slice(i, j).map(String).join('.');
        if (Object.prototype.hasOwnProperty.call(node, joined)){ key = joined; break; }
      }
      if (key == null) break;
      path.push(key);
      node = node[key];
      i = j;
    }
  }
  var exact = i === tokens.length;
  var loc = jsonLocate(text, path);
  while (!loc && path.length){ path.pop(); loc = jsonLocate(text, path); exact = false; }
  if (!loc) loc = jsonLocate(text, []);
  if (!loc) return null;
  return {start: loc.start, end: loc.end, exact: exact};
}

/* ---------------- draft vs baseline ---------------- */

function diffSpecs(oldObj, newObj){
  var findings = [], ranks = new Map(), ends = new Map(), ordinal = 0;
  function object(v){ return v && typeof v === 'object' && !Array.isArray(v) ? v : {}; }
  function list(v){ return Array.isArray(v) ? v : []; }
  function index(v, path){
    ranks.set(JSON.stringify(path), ordinal++);
    if (v && typeof v === 'object') Object.keys(v).forEach(function(k){
      index(v[k], path.concat([Array.isArray(v) ? Number(k) : k]));
    });
    ends.set(JSON.stringify(path), ordinal);
  }
  index(newObj, []);
  function existing(path){
    path = path.slice();
    while (path.length && !ranks.has(JSON.stringify(path))) path.pop();
    return path;
  }
  function add(path, kind, text, order){
    var target = existing(path), key = JSON.stringify(target);
    findings.push({path: builderPathString(target), kind: kind, text: text,
      order: order == null ? (kind === 'removed' ? ends.get(key) - 0.5 : ranks.get(key)) : order,
      seq: findings.length});
  }
  function fields(a, b, keys, path, label){
    a = object(a); b = object(b);
    keys.forEach(function(k){
      if (JSON.stringify(a[k]) !== JSON.stringify(b[k]))
        add(path.concat([k]), 'changed', label + ' ' + k + ' changed');
    });
  }
  /* compare EVERY key present on either side (minus the identity keys the
     pairing used) — a whitelist here silently hides material edits like a
     node link, a panel initial, or a contract row's hot flag */
  function allFields(a, b, path, label, except){
    a = object(a); b = object(b);
    var seen = {};
    Object.keys(a).concat(Object.keys(b)).forEach(function(k){
      if (seen[k] || (except && except.indexOf(k) >= 0)) return;
      seen[k] = true;
      if (JSON.stringify(a[k]) !== JSON.stringify(b[k]))
        add(path.concat([k]), 'changed', label + ' ' + k + ' changed');
    });
  }
  /* Match full identity first; optional similarity disambiguates repeated
     headings. A unique endpoint residual allows an edge kind edit. */
  function pairs(a, b, same, score){
    var matches = new Map(), used = new Set(), candidates = [];
    a.forEach(function(x, i){ b.forEach(function(y, j){
      if (same(x, y)) candidates.push({i: i, j: j, score: score ? score(x, y) : 0});
    }); });
    candidates.sort(function(x, y){
      return y.score - x.score || Math.abs(x.i - x.j) - Math.abs(y.i - y.j) || x.i - y.i || x.j - y.j;
    });
    candidates.forEach(function(c){
      if (!used.has(c.i) && !matches.has(c.j)){ used.add(c.i); matches.set(c.j, c.i); }
    });
    return {matches: matches, used: used};
  }
  function compareList(a, b, path, key, label, except, endpoints){
    a = list(a); b = list(b);
    var match = pairs(a, b, function(x, y){
      return key(object(x)) === key(object(y)) && (!endpoints || endpoints(x) === endpoints(y));
    });
    if (endpoints) a.forEach(function(x, i){
      if (match.used.has(i)) return;
      var oldLeft = a.filter(function(v, k){ return !match.used.has(k) && endpoints(v) === endpoints(x); });
      var newLeft = b.map(function(v, j){ return j; }).filter(function(j){
        return !match.matches.has(j) && endpoints(b[j]) === endpoints(x);
      });
      if (oldLeft.length === 1 && newLeft.length === 1){ match.used.add(i); match.matches.set(newLeft[0], i); }
    });
    b.forEach(function(v, j){
      var itemPath = path.concat([j]), name = label + ' ' + key(object(v));
      if (!match.matches.has(j)) add(itemPath, 'added', name + ' added');
      else allFields(a[match.matches.get(j)], v, itemPath, name, except);
    });
    a.forEach(function(v, i){
      if (!match.used.has(i)) add(path, 'removed', label + ' ' + key(object(v)) + ' removed');
    });
  }
  function page(raw){ return object(object(raw).page || raw); }
  function sections(raw){
    var p = page(raw), base = object(raw).page ? ['page'] : [];
    var key = Array.isArray(p.blocks) ? 'blocks' : 'sections', result = [], tabs = [];
    if (p.nodes && p.rows) return {refs: [{value: {diagram: p}, path: [], diagram: []}], tabs: [], base: base};
    list(p[key]).forEach(function(b, i){
      var path = base.concat([key, i]);
      if (Array.isArray(object(b).tabs)) b.tabs.forEach(function(t, j){
        var tabPath = path.concat(['tabs', j]);
        tabs.push({value: object(t), path: tabPath});
        list(object(t).sections).forEach(function(sec, k){
          var sp = tabPath.concat(['sections', k]);
          result.push({value: object(sec), path: sp, diagram: sp.concat(['diagram'])});
        });
      });
      else result.push({value: object(b), path: path, diagram: path.concat(['diagram'])});
    });
    return {refs: result, tabs: tabs, base: base.concat([key])};
  }
  function heading(ref){ return typeof ref.value.heading === 'string' ? ref.value.heading : ''; }
  function similarity(a, b){
    var an = Object.keys(object(object(a.value.diagram).nodes));
    var bn = object(object(b.value.diagram).nodes);
    var af = list(object(a.value.contract).fields), bf = list(object(b.value.contract).fields);
    var shared = an.filter(function(k){ return Object.prototype.hasOwnProperty.call(bn, k); }).length;
    af.forEach(function(f){ if (bf.some(function(g){ return object(f).k === object(g).k; })) shared++; });
    return shared + (object(a.value.contract).title === object(b.value.contract).title ? 0.25 : 0);
  }
  var old = sections(oldObj), next = sections(newObj);
  var tabs = pairs(old.tabs, next.tabs, function(a, b){ return a.value.label === b.value.label; });
  function container(path){
    var target = null, key = JSON.stringify(path);
    tabs.matches.forEach(function(oi, ni){
      var ot = old.tabs[oi], nt = next.tabs[ni];
      if (JSON.stringify(ot.path.concat(['sections'])) === key) target = nt.path.concat(['sections']);
      if (!target && JSON.stringify(ot.path.slice(0, -1)) === key) target = nt.path.slice(0, -1);
    });
    if (!target){
      target = next.base.concat(path.slice(old.base.length));
      if (!Array.isArray(specValueAt(newObj, target))) target = next.base;
    }
    return existing(target);
  }
  fields(page(oldObj), page(newObj), ['title', 'skin'], object(newObj).page ? ['page'] : [], 'page');
  var match = pairs(old.refs, next.refs, function(a, b){ return heading(a) === heading(b); }, similarity);
  next.refs.forEach(function(ref, j){
    var label = heading(ref) || 'section ' + (j + 1), path = ref.path;
    if (!match.matches.has(j)){ add(path, 'added', 'section ' + label + ' added'); return; }
    var prev = old.refs[match.matches.get(j)];
    var a = object(prev.value.diagram), b = object(ref.value.diagram), dp = ref.diagram;
    var an = object(a.nodes), bn = object(b.nodes);
    Object.keys(bn).forEach(function(id){
      var np = dp.concat(['nodes', id]);
      if (!Object.prototype.hasOwnProperty.call(an, id)) add(np, 'added', label + ': node ' + id + ' added');
      else allFields(an[id], bn[id], np, label + ': node ' + id);
    });
    Object.keys(an).forEach(function(id){
      if (!Object.prototype.hasOwnProperty.call(bn, id)) add(dp.concat(['nodes']), 'removed', label + ': node ' + id + ' removed');
    });
    function endpoints(e){ e = object(e); return JSON.stringify([e.from, e.to]); }
    compareList(a.edges, b.edges, dp.concat(['edges']), function(e){
      return e.from + '->' + e.to + (e.kind ? '(' + e.kind + ')' : '');
    }, label + ': edge', ['from', 'to'], endpoints);
    var as = list(a.steps), bs = list(b.steps);
    if (as.length !== bs.length) add(dp.concat(['steps']), 'changed', label + ': step count changed (' + as.length + ' → ' + bs.length + ')');
    bs.forEach(function(step, i){
      if (i < as.length) allFields(as[i], step, dp.concat(['steps', i]), label + ': step ' + (i + 1));
    });
    compareList(a.panels, b.panels, dp.concat(['panels']), function(p){ return p.id; }, label + ': panel', ['id']);
    compareList(object(prev.value.contract).fields, object(ref.value.contract).fields,
      path.concat(['contract', 'fields']), function(f){ return f.k; }, label + ': contract field', ['k']);
  });
  old.refs.forEach(function(ref, i){
    if (match.used.has(i)) return;
    var parent = ref.path.slice(0, -1), target = container(parent), order;
    /* Place a removed section before its next surviving old neighbour. */
    for (var k = i + 1; k < old.refs.length; k++){
      if (JSON.stringify(old.refs[k].path.slice(0, -1)) !== JSON.stringify(parent)) continue;
      var found = -1;
      match.matches.forEach(function(oi, ni){ if (oi === k) found = ni; });
      if (found >= 0){
        if (JSON.stringify(next.refs[found].path.slice(0, -1)) !== JSON.stringify(target)) continue;
        order = ranks.get(JSON.stringify(next.refs[found].path)) - 0.5;
        break;
      }
    }
    add(target, 'removed', 'section ' + (heading(ref) || 'section ' + (i + 1)) + ' removed', order);
  });
  next.tabs.forEach(function(t, i){
    if (!tabs.matches.has(i)) add(t.path.concat(['label']), 'added', 'tab ' + t.value.label + ' added');
  });
  old.tabs.forEach(function(t, i){
    if (!tabs.used.has(i)) add(container(t.path.slice(0, -1)), 'removed', 'tab ' + t.value.label + ' removed');
  });
  findings.sort(function(a, b){ return a.order - b.order || a.seq - b.seq; });
  return findings.map(function(f){ return {path: f.path, kind: f.kind, text: f.text}; });
}

function diffSpecTexts(baselineText, currentText){
  var oldObj, newObj;
  try { oldObj = JSON.parse(baselineText); }
  catch (ex){ return {error: 'baseline JSON is unparseable'}; }
  try { newObj = JSON.parse(currentText); }
  catch (ex){ return {error: 'current JSON is unparseable'}; }
  return {findings: diffSpecs(oldObj, newObj)};
}

/* ---------------- tab management ----------------
   Tabs are addressed by BLOCK index (the position in the page's
   blocks/sections list — the same index the engine bakes into each tab
   button's id "tab-<block>-<tab>") plus the tab index inside that
   block's tabs list. */

function builderTabPath(raw, blockIdx, tabIdx){
  var base, page;
  if (raw && raw.page){ page = raw.page; base = ['page']; }
  else if (raw && (raw.blocks || raw.sections)){ page = raw; base = []; }
  else return null;
  var key = page.blocks ? 'blocks' : 'sections';
  var block = (page[key] || [])[blockIdx];
  if (!block || !Array.isArray(block.tabs) || !block.tabs[tabIdx]) return null;
  return base.concat([key, blockIdx, 'tabs', tabIdx]);
}

var BUILDER_TAB_TEMPLATE = [
  '{',
  '  "label": "New tab",',
  '  "sections": [' + BUILDER_SECTION_TEMPLATE.split('\n').join('\n  ') + ']',
  '}'
].join('\n');

/* a whole tabs container: two tabs, one starter section each — the
   "+ tab" button on a selected tab grows it from there */
var BUILDER_TABS_TEMPLATE = [
  '{',
  '  "tabs": [',
  '    ' + BUILDER_TAB_TEMPLATE.replace('"New tab"', '"Tab one"').split('\n').join('\n    ') + ',',
  '    ' + BUILDER_TAB_TEMPLATE.replace('"New tab"', '"Tab two"').split('\n').join('\n    '),
  '  ]',
  '}'
].join('\n');

function planAddTabs(text, raw){
  /* append a tabs container to the page's block list — same shape rules
     as planAddSection */
  var base, page;
  if (raw && raw.page){ page = raw.page; base = ['page']; }
  else if (raw && (raw.blocks || raw.sections)){ page = raw; base = []; }
  else if (raw && raw.nodes && raw.rows)
    return {error: 'this spec is a bare diagram — wrap it as {"page": {"blocks": [ {...} ]}} to hold tabs'};
  else return {error: 'no page to add tabs to'};
  var key = page.blocks ? 'blocks' : 'sections';
  if (!jsonLocate(text, base.concat([key])))
    return {error: 'could not find the ' + key + ' list in the editor text'};
  var r = jsonInsertMember(text, base.concat([key]), null, BUILDER_TABS_TEMPLATE);
  if (!r) return {error: 'could not edit the ' + key + ' list in the editor text'};
  return {text: r.text, start: r.start, end: r.end, kind: 'tabs',
          block: (page[key] || []).length,
          index: specSectionPaths(raw).length};
}

function planAddTab(text, raw, blockIdx, afterIdx){
  /* insert a renderable tab (one starter section) directly after the
     tab the operator is looking at */
  var path = builderTabPath(raw, blockIdx, afterIdx);
  if (!path) return {error: 'tab not found — reselect and try again'};
  var tabsPath = path.slice(0, -1);
  var r = jsonInsertArrayItemAfter(text, tabsPath, afterIdx, BUILDER_TAB_TEMPLATE);
  if (!r) return {error: 'could not edit the tabs list in the editor text'};
  return {text: r.text, start: r.start, end: r.end, kind: 'tab',
          block: blockIdx, index: afterIdx + 1};
}

function planDeleteTab(text, raw, blockIdx, tabIdx){
  var path = builderTabPath(raw, blockIdx, tabIdx);
  if (!path) return {error: 'tab not found — reselect and try again'};
  var tabsPath = path.slice(0, -1);
  var tabs = specValueAt(raw, tabsPath);
  if (Array.isArray(tabs) && tabs.length === 1)
    return {error: 'this is the block\u2019s last tab — delete its sections instead, or remove the whole tabs block in the JSON'};
  var r = jsonRemoveMember(text, tabsPath, tabIdx);
  if (!r) return {error: 'could not edit the tabs list in the editor text'};
  return r;
}

function planMoveTab(text, raw, blockIdx, tabIdx, delta){
  var path = builderTabPath(raw, blockIdx, tabIdx);
  if (!path) return {error: 'tab not found — reselect and try again'};
  var tabsPath = path.slice(0, -1);
  var tabs = specValueAt(raw, tabsPath);
  var to = tabIdx + delta;
  if (to < 0 || to >= tabs.length) return {error: 'already at that end'};
  var r = builderRewrite(text, raw, tabsPath, function(copy){
    var item = copy.splice(tabIdx, 1)[0];
    copy.splice(to, 0, item);
  });
  if (r.error) return r;
  r.kind = 'tab'; r.block = blockIdx; r.index = to;
  return r;
}

/* ---------------- reordering ---------------- */

/* swap two items of one JSON array textually — each item keeps its own
   formatting, only the two spans trade places. Returns the swapped text
   plus the new spans: first = the slot at the SMALLER index, second = the
   slot at the larger. */
function jsonSwapListItems(text, listPath, i, j){
  if (i === j) return null;
  if (i > j){ var t = i; i = j; j = t; }
  var a = jsonLocate(text, listPath.concat([i]));
  var b = jsonLocate(text, listPath.concat([j]));
  if (!a || !b) return null;
  return {
    text: text.slice(0, a.start) + text.slice(b.start, b.end) +
          text.slice(a.end, b.start) + text.slice(a.start, a.end) + text.slice(b.end),
    first: {start: a.start, end: a.start + (b.end - b.start)},
    second: {start: b.end - (a.end - a.start), end: b.end}
  };
}

/* move a section one slot within ITS OWN list (the top-level blocks list,
   or its tab's sections list). A neighbor blocks-list entry may be a tabs
   container — the move hops over it whole. Returns newPath (the section's
   list slot after the move); the caller recomputes the flat ordinal from
   it, because hopping a tabs container shifts ordinals by its section
   count. */
function planMoveSection(text, raw, sectionIdx, delta){
  var rec = specSectionPaths(raw)[sectionIdx];
  if (!rec) return {error: 'section not found — reselect and try again'};
  var spath = rec.section;
  if (!spath.length) return {error: 'a bare-diagram page has only one section'};
  var listPath = spath.slice(0, -1);
  var idx = spath[spath.length - 1];
  var list = specValueAt(raw, listPath);
  if (!Array.isArray(list)) return {error: 'section list not found in the editor text'};
  var to = idx + delta;
  if (to < 0) return {error: 'already first in its list'};
  if (to >= list.length) return {error: 'already last in its list'};
  var swap = jsonSwapListItems(text, listPath, idx, to);
  if (!swap) return {error: 'could not locate both sections in the editor text'};
  var span = delta < 0 ? swap.first : swap.second;
  return {text: swap.text, start: span.start, end: span.end,
          kind: 'section', newPath: listPath.concat([to])};
}

/* swap the LAYOUT positions of two nodes: every appearance in rows
   (slots and stacks) and floats trades ids. Node definitions, edges, and
   steps keep their ids — only placement moves. */
function planSwapNodes(text, raw, sectionIdx, idA, idB){
  if (idA === idB) return {error: 'drop on a DIFFERENT node to swap places'};
  var rec = specSectionPaths(raw)[sectionIdx];
  if (!rec) return {error: 'section not found — reselect and try again'};
  var d = specValueAt(raw, rec.diagram);
  if (!d) return {error: 'no diagram in this section'};
  var found = {a: false, b: false};
  function sw(id){
    if (id === idA){ found.a = true; return idB; }
    if (id === idB){ found.b = true; return idA; }
    return id;
  }
  var rows = Array.isArray(d.rows) ? d.rows.map(function(row){
    if (!Array.isArray(row)) return row;
    return row.map(function(slot){ return Array.isArray(slot) ? slot.map(sw) : sw(slot); });
  }) : null;
  var floats = Array.isArray(d.floats) ? d.floats.map(function(f){
    if (!f || typeof f !== 'object' || typeof f.id !== 'string') return f;
    var nid = sw(f.id);
    if (nid === f.id) return f;
    var copy = {};
    Object.keys(f).forEach(function(k){ copy[k] = f[k]; });
    copy.id = nid;
    return copy;
  }) : null;
  if (!found.a || !found.b)
    return {error: 'node "' + (found.a ? idB : idA) + '" has no layout slot (rows or floats) to swap'};
  var pairs = [];
  if (rows && JSON.stringify(rows) !== JSON.stringify(d.rows)) pairs.push(['rows', JSON.stringify(rows)]);
  if (floats && JSON.stringify(floats) !== JSON.stringify(d.floats)) pairs.push(['floats', JSON.stringify(floats)]);
  if (!pairs.length) return {error: 'nothing changed'};
  var plan = planSetFields(text, raw, rec.diagram, pairs);
  if (plan.error) return plan;
  plan.kind = 'node';
  return plan;
}

function planStackNodes(text, raw, sectionIdx, nodeIds){
  /* collect the given nodes into ONE vertical stack (a nested array) in
     diagram.rows. Every selected id is lifted from wherever it sits; the
     stack lands at the outer slot the first selected id (flat-row order)
     occupied. Non-selected nodes keep their positions; empty slots and
     rows are dropped. */
  var rec = specSectionPaths(raw)[sectionIdx];
  if (!rec) return {error: 'section not found — reselect and try again'};
  var d = specValueAt(raw, rec.diagram);
  if (!d || !Array.isArray(d.rows)) return {error: 'no rows layout in this section to stack into'};
  var want = {};
  (nodeIds || []).forEach(function(id){ if (typeof id === 'string') want[id] = true; });
  var wantList = Object.keys(want);
  if (wantList.length < 2) return {error: 'select at least two nodes to stack'};
  /* flat-row order of the selected ids, and which of them actually sit in rows */
  var ordered = [], seen = {};
  d.rows.forEach(function(row){
    if (!Array.isArray(row)) return;
    row.forEach(function(slot){
      (Array.isArray(slot) ? slot : [slot]).forEach(function(s){
        if (typeof s === 'string' && want[s] && !seen[s]){ seen[s] = true; ordered.push(s); }
      });
    });
  });
  var missing = wantList.filter(function(id){ return !seen[id]; });
  if (missing.length) return {error: 'node "' + missing[0] + '" has no row slot to stack (it may be a float)'};
  var anchor = ordered[0];
  var placed = false, newRows = [];
  d.rows.forEach(function(row){
    if (!Array.isArray(row)){ newRows.push(row); return; }
    var newRow = [];
    row.forEach(function(slot){
      if (Array.isArray(slot)){
        var remaining = slot.filter(function(s){ return !(typeof s === 'string' && want[s]); });
        if (slot.indexOf(anchor) >= 0 && !placed){ newRow.push(ordered.slice()); placed = true; }
        if (remaining.length > 1) newRow.push(remaining);
        else if (remaining.length === 1) newRow.push(remaining[0]);
      } else if (typeof slot === 'string' && want[slot]){
        if (slot === anchor && !placed){ newRow.push(ordered.slice()); placed = true; }
        /* other selected string slots are simply lifted out */
      } else {
        newRow.push(slot);
      }
    });
    if (newRow.length) newRows.push(newRow);
  });
  if (!placed) return {error: 'could not place the stack'};
  if (JSON.stringify(newRows) === JSON.stringify(d.rows))
    return {error: 'those nodes are already one stack'};
  var plan = planSetFields(text, raw, rec.diagram, [['rows', JSON.stringify(newRows)]]);
  if (plan.error) return plan;
  plan.kind = 'node';
  return plan;
}

/* ---------------- multi-select: bulk planners ----------------
   A multi-selection is HOMOGENEOUS (one kind) — mixed-kind bulk deletes
   interact with cascades (a node delete prunes edges/steps) in ways that
   silently invalidate sibling targets. Deletes apply highest-index-first
   per section so earlier deletions cannot shift later targets. */
var BUILDER_MULTI_KINDS = ['node', 'edge', 'step', 'panel', 'bullet', 'crow'];

function builderDeletePlan(text, raw, t){
  if (t.kind === 'tab') return planDeleteTab(text, raw, t.block, t.tab);
  if (t.kind === 'group') return planDeleteGroup(text, raw, t.section, t.id);
  if (t.kind === 'node') return planDeleteNode(text, raw, t.section, t.id);
  if (t.kind === 'edge') return planDeleteEdge(text, raw, t.section, t.index);
  if (t.kind === 'step') return planDeleteStep(text, raw, t.section, t.index);
  if (t.kind === 'panel') return planDeletePanel(text, raw, t.section, t.index);
  var rec = specSectionPaths(raw)[t.section];
  if (!rec) return {error: 'no such section'};
  if (t.kind === 'bullet') return planDeleteListItem(text, raw, rec.section.concat(['bullets']), t.index);
  if (t.kind === 'para'){
    var sec = specValueAt(raw, rec.section);
    if (sec && typeof sec.text === 'string') return planSetField(text, raw, rec.section, 'text', null);
    return planDeleteListItem(text, raw, rec.section.concat(['text']), t.index);
  }
  if (t.kind === 'crow') return planDeleteListItem(text, raw, rec.section.concat(['contract', 'fields']), t.index);
  return planDeleteSection(text, raw, t.section);
}

function planBulkSetField(text, targets, key, valueTextOrNull){
  var cur = text;
  for (var i = 0; i < targets.length; i++){
    var raw;
    try { raw = JSON.parse(cur); }
    catch (ex){ return {error: 'bulk stopped: the JSON no longer parses (' + ex.message + ')'}; }
    var path = builderTargetPath(raw, targets[i]);
    if (!path) return {error: 'selection ' + (i + 1) + ' no longer resolves — re-render and reselect'};
    var plan = planSetField(cur, raw, path, key, valueTextOrNull);
    if (plan.error) return {error: 'selection ' + (i + 1) + ': ' + plan.error};
    cur = plan.text;
  }
  return {text: cur, count: targets.length};
}

function planBulkDelete(text, targets){
  var list = targets.slice().sort(function(a, b){
    if ((a.section || 0) !== (b.section || 0)) return (b.section || 0) - (a.section || 0);
    return (typeof b.index === 'number' ? b.index : 0) - (typeof a.index === 'number' ? a.index : 0);
  });
  var cur = text;
  for (var i = 0; i < list.length; i++){
    var raw;
    try { raw = JSON.parse(cur); }
    catch (ex){ return {error: 'bulk stopped: the JSON no longer parses (' + ex.message + ')'}; }
    var plan = builderDeletePlan(cur, raw, list[i]);
    if (plan.error) return {error: 'selection ' + (i + 1) + ': ' + plan.error};
    cur = plan.text;
  }
  return {text: cur, count: list.length};
}

/* ---------------- step contract editing ----------------
   A step's membership: hops (edge / edges), lit nodes (nodes), and
   panel patches (panels). Toggles normalize the hop shape: zero hops
   removes the key (edgeless steps are legal), one hop stores
   edge: "a->b", two or more store edges: [...]. */

function builderStepHops(st){
  /* tolerate the malformed both-keys shape: merge edge and edges so a
     later toggle's rebuild cannot silently drop listed hops */
  if (!st) return [];
  var out = [];
  if (typeof st.edge === 'string') out.push(st.edge);
  if (Array.isArray(st.edges)) st.edges.forEach(function(k){
    if (typeof k === 'string' && out.indexOf(k) < 0) out.push(k);
  });
  Object.keys(stepFailures(st)).forEach(function(key){if (out.indexOf(key) < 0) out.push(key);});
  return out;
}

function builderStepAt(raw, sectionIdx, stepIdx){
  var rec = specSectionPaths(raw)[sectionIdx];
  if (!rec) return null;
  var d = specValueAt(raw, rec.diagram);
  if (!d || !Array.isArray(d.steps) || !d.steps[stepIdx]) return null;
  return {rec: rec, d: d, st: d.steps[stepIdx],
          path: rec.diagram.concat(['steps', stepIdx])};
}

function planStepToggleHop(text, raw, sectionIdx, stepIdx, key){
  var got = builderStepAt(raw, sectionIdx, stepIdx);
  if (!got) return {error: 'step not found — reselect and try again'};
  var hops = builderStepHops(got.st);
  var has = hops.indexOf(key) >= 0;
  if (!has){
    var known = (got.d.edges || []).some(function(e){ return e && builderEdgeKey(e) === key; });
    if (!known) return {error: 'no edge "' + key + '" in this diagram'};
  }
  var next = has ? hops.filter(function(k){ return k !== key; }) : hops.concat([key]);
  var r = builderRewrite(text, raw, got.path, function(st){
    var failures = stepFailures(st);
    if (has) delete failures[key];
    if (has && Array.isArray(st.packets)) st.packets = st.packets.filter(function(pk){return pk.edge !== key;});
    var delivered = next.filter(function(k){return !Object.prototype.hasOwnProperty.call(failures,k);});
    delete st.edge; delete st.edges;
    if (delivered.length === 1) st.edge = delivered[0];
    else if (delivered.length > 1) st.edges = delivered;
    if (Object.keys(failures).length) st.failures = failures; else delete st.failures;
  });
  if (r.error) return r;
  r.added = !has;
  return r;
}

function planStepCommunication(text,raw,sectionIdx,stepIdx,key,outcome){
  var got = builderStepAt(raw,sectionIdx,stepIdx);
  if (!got) return {error:'Select a step first.'};
  if (['delivered','dropped','blocked'].indexOf(outcome) < 0) return {error:'Choose delivered, dropped or blocked.'};
  if (!(got.d.edges || []).some(function(e){return e && builderEdgeKey(e) === key;})) return {error:'Choose an existing edge.'};
  return builderRewrite(text,raw,got.path,function(st){
    var failures = stepFailures(st), delivered = builderStepHops(st).filter(function(k){
      return k !== key && !Object.prototype.hasOwnProperty.call(failures,k);
    });
    if (outcome === 'delivered'){ delete failures[key]; delivered.push(key); }
    else failures[key] = outcome;
    delete st.edge; delete st.edges;
    if (delivered.length === 1) st.edge = delivered[0]; else if (delivered.length > 1) st.edges = delivered;
    if (Object.keys(failures).length) st.failures = failures; else delete st.failures;
  });
}

var STEP_TONE_TOKENS = ['alert', 'warn', 'ok', 'dim', 'base'];
function planStepTone(text, raw, sectionIdx, stepIdx, nodeId, tokenOrNull){
  var got = builderStepAt(raw, sectionIdx, stepIdx);
  if (!got) return {error: 'step not found — reselect and try again'};
  if (!(got.d.nodes && Object.prototype.hasOwnProperty.call(got.d.nodes, nodeId)))
    return {error: 'no node "' + nodeId + '" in this diagram'};
  if (tokenOrNull != null && STEP_TONE_TOKENS.indexOf(tokenOrNull) < 0)
    return {error: 'tone must be one of ' + STEP_TONE_TOKENS.join(', ')};
  return builderRewrite(text, raw, got.path, function(st){
    var tone = Object.create(null);
    /* tolerant read (not stepTonePatch: that helper lives in the validator
       bundle, and this file is unit-tested standalone) */
    var cur = (st.tone && typeof st.tone === 'object' && !Array.isArray(st.tone)) ? st.tone : {};
    Object.keys(cur).forEach(function(k){ tone[k] = cur[k]; });
    if (tokenOrNull == null) delete tone[nodeId];
    else tone[nodeId] = tokenOrNull;
    /* keep the null-prototype object: assigning "__proto__" into a plain
       {} would hit the inherited setter and silently drop the entry.
       JSON.stringify serializes own properties of a null-proto object. */
    if (Object.keys(tone).length) st.tone = tone; else delete st.tone;
  });
}

function planStepToggleNode(text, raw, sectionIdx, stepIdx, nodeId){
  var got = builderStepAt(raw, sectionIdx, stepIdx);
  if (!got) return {error: 'step not found — reselect and try again'};
  var list = Array.isArray(got.st.nodes) ? got.st.nodes : [];
  var has = list.indexOf(nodeId) >= 0;
  if (!has && !(got.d.nodes && Object.prototype.hasOwnProperty.call(got.d.nodes, nodeId)))
    return {error: 'no node "' + nodeId + '" in this diagram'};
  var r = builderRewrite(text, raw, got.path, function(st){
    var next = (Array.isArray(st.nodes) ? st.nodes : []).filter(function(n){ return n !== nodeId; });
    if (!has) next.push(nodeId);
    if (next.length) st.nodes = next; else delete st.nodes;
  });
  if (r.error) return r;
  r.added = !has;
  return r;
}

function planStepTogglePanel(text, raw, sectionIdx, stepIdx, panelId){
  var got = builderStepAt(raw, sectionIdx, stepIdx);
  if (!got) return {error: 'step not found — reselect and try again'};
  var has = !!(got.st.panels && Object.prototype.hasOwnProperty.call(got.st.panels, panelId));
  if (!has && !(got.d.panels || []).some(function(p){ return p && p.id === panelId; }))
    return {error: 'no panel "' + panelId + '" in this diagram'};
  var r = builderRewrite(text, raw, got.path, function(st){
    if (has){
      delete st.panels[panelId];
      if (!Object.keys(st.panels).length) delete st.panels;
    } else {
      if (!st.panels) st.panels = {};
      st.panels[panelId] = {};
    }
  });
  if (r.error) return r;
  r.added = !has;
  return r;
}

function planPrimaryPanel(text, raw, sectionIdx, panelId){
  var got = builderDiagram(text, raw, sectionIdx);
  if (got.error) return got;
  if (panelId != null && !(got.d.panels || []).some(function(p){ return p && p.id === panelId; }))
    return {error:'Choose an existing panel for the centerpiece.'};
  return builderRewrite(text, raw, got.path, function(d){
    if (panelId == null) delete d.primaryPanel; else d.primaryPanel = panelId;
  });
}

/* Layout selection must remain available even when a diagram has a stepper. */
function builderHomemapClickTarget(element, getStepper, currentTarget){
  var card = element.closest && element.closest('.pt-homemap[data-dv-panel]');
  var section = card && card.closest('.doc-sec[data-dv-section]');
  if (!section) return null;
  var explicitLayout = element.closest('[data-home-layout]');
  if (!explicitLayout && element.closest('a, button, summary, [role="button"], input, select, textarea')) return null;
  var ordinal = Number(section.getAttribute('data-dv-section')), index = Number(card.getAttribute('data-dv-panel'));
  if (!Number.isInteger(ordinal) || !Number.isInteger(index)) return null;
  var player = getStepper(ordinal);
  var editingLayout = currentTarget && currentTarget.kind === 'panel' && currentTarget.section === ordinal && currentTarget.index === index;
  var marker = element.closest('[data-device], [data-subject], [data-home-room]');
  if (!explicitLayout && !editingLayout && marker && player && player.mode() === 'step')
    return {section:ordinal, kind:'step', index:player.sourceIndex()};
  return {section:ordinal, kind:'panel', index:index, el:card};
}

/* Read both snapshots through the engine, following the selected branch.
   Removing one authored key restores its inherited value, never a copied
   snapshot that would freeze unrelated devices or people. */
function builderHomemapStep(d, stepIndex, panelId, pathId){
  var panel = (d.panels || []).find(function(p){ return p && p.id === panelId && p.type === 'homemap'; });
  var route = diagramPathList(d).find(function(p){ return p.id === pathId && p.indices.indexOf(stepIndex) >= 0; }) ||
    diagramPathList(d).find(function(p){ return p.indices.indexOf(stepIndex) >= 0; });
  if (!panel || !route) return {error:'Select a homemap and a step in this path.'};
  var localIndex = route.indices.indexOf(stepIndex), active = diagramForPath(d, route.id);
  var states = foldHomemapStates(panel, active.steps), state = states[localIndex];
  var initial = Object.assign(Object.create(null), panel.initial || {}, {signals:[]});
  var patch = (stepPanelPatch(d.steps[stepIndex]) || {})[panelId] || {};
  return {panel:panel, patch:patch, state:state, position:localIndex,
    model:homemapModel(panel, state), before:homemapModel(panel, localIndex ? states[localIndex - 1] : initial)};
}

/* Shared geometry edits never write step patches or move room occupants. */
function planHomemapLayoutPosition(text, raw, sectionIdx, panelId, kind, key, point){
  var got = builderDiagram(text, raw, sectionIdx);
  if (got.error) return got;
  var panels = got.d.panels || [], pi = panels.findIndex(function(p){ return p && p.id === panelId && p.type === 'homemap'; });
  if (pi < 0) return {error:'Homemap not found — reselect and try again.'};
  var panel = panels[pi], index = -1, item, list;
  var panelPath = got.path.concat(['panels', pi]);
  if (kind === 'outline'){
    if (!homemapSubjectPosition(point)) return {error:'Choose a finite house position.'};
    item = Object.assign({}, panel.outline, homemapModel(panel).outline, point);
    if (!homemapSubjectPosition(item) || !isFiniteNum(item.w) || !isFiniteNum(item.h) ||
        item.w < 20 || item.h < 20 || item.x < 0 || item.y < 0 || item.x + item.w > 320 || item.y + item.h > 180)
      return {error:'Keep the house inside the frame, at least 20×20.'};
    return planSetField(text, raw, panelPath, 'outline', JSON.stringify(item));
  }
  if (kind === 'device'){
    list = 'devices';
    if (homemapModel(panel).devices.some(function(d){ return d.id === key; }))
      index = panel.devices.findIndex(function(d){ return d && d.id === key; });
  } else if (kind === 'room'){
    list = 'rooms';
    if (Number.isInteger(key) && Array.isArray(panel.rooms) && homemapRooms(panel).indexOf(panel.rooms[key]) >= 0) index = key;
  } else if (kind === 'subject'){
    list = 'subjects';
    if (homemapSubjects(panel).some(function(s){return s.id === key;}))
      index = panel.subjects.findIndex(function(s){return s && s.id === key;});
  }
  if (index < 0) return {error:'Choose an existing device, room, or subject.'};
  item = panel[list][index];
  var resize = kind === 'room' && point && (point.w !== undefined || point.h !== undefined);
  var w = resize ? point.w : item.w, h = resize ? point.h : item.h;
  if (resize && (!isFiniteNum(w) || !isFiniteNum(h) || w <= 0 || h <= 0)) return {error:'Rooms need a positive width and height.'};
  var maxX = 320 - (kind === 'room' ? w : 0), maxY = 180 - (kind === 'room' ? h : 0);
  if (!homemapSubjectPosition(point) || point.x < 0 || point.y < 0 || point.x > maxX || point.y > maxY)
    return {error:'Keep the whole item inside the 320×180 map.'};
  var fields = [['x', JSON.stringify(point.x)], ['y', JSON.stringify(point.y)]];
  if (resize) fields.push(['w', JSON.stringify(w)], ['h', JSON.stringify(h)]);
  var plan = planSetFields(text, raw, panelPath.concat([list, index]), fields);
  if (!plan.error && kind === 'subject' && panel.initial && homemapSubjectPosition(panel.initial[key]))
    return planSetFields(plan.text, JSON.parse(plan.text), panelPath.concat(['initial', key]), fields);
  return plan;
}

function builderHomemapLayoutDrag(item, start, at, resize, minimum){
  var dx = at.x - start.x, dy = at.y - start.y;
  if (resize) return {x:item.x, y:item.y,
    w:clamp(Math.round(item.w + dx), minimum || 1, 320 - item.x),
    h:clamp(Math.round(item.h + dy), minimum || 1, 180 - item.y)};
  return {x:clamp(Math.round(item.x + dx), 0, 320 - (item.w || 0)),
    y:clamp(Math.round(item.y + dy), 0, 180 - (item.h || 0))};
}

function builderHomemapLayoutScene(panel){
  var state = Object.assign(Object.create(null), panel.initial || {}), hidden = [];
  var model = homemapModel(panel, state);
  model.subjects.forEach(function(s){
    if (s.hidden) hidden.push(s.id);
    state[s.id] = {x:s.x, y:s.y}; /* hidden subjects still have draggable starting positions */
  });
  return {state:state, model:homemapModel(panel, state), hidden:hidden};
}

function planStepHomemapField(text, raw, sectionIdx, stepIdx, panelId, key, value){
  var got = builderStepAt(raw, sectionIdx, stepIdx);
  if (!got) return {error:'Step not found — reselect and try again.'};
  var p = (got.d.panels || []).find(function(p){ return p && p.id === panelId && p.type === 'homemap'; });
  if (!p) return {error:'Homemap not found — reselect and try again.'};
  var model = homemapModel(p), device = model.devices.find(function(d){ return d.id === key; });
  var subject = model.subjects.find(function(s){ return s.id === key; });
  if (!device && !subject && key !== 'signals') return {error:'Unknown homemap field.'};
  if (value !== undefined){
    if (device && HOMEMAP_STATES[device.kind].indexOf(value) < 0) return {error:'Choose a valid device state.'};
    if (subject && value !== null && (!homemapSubjectPosition(value) || value.x < 0 || value.x > 320 || value.y < 0 || value.y > 180))
      return {error:'Use a position within the map: x 0–320, y 0–180.'};
    if (key === 'signals' && (!Array.isArray(value) || value.some(function(s){
      return !s || !model.devices.some(function(d){ return d.id === s.from; }) ||
        !model.devices.some(function(d){ return d.id === s.to; });
    }))) return {error:'Each signal needs two existing devices.'};
  }
  return builderRewrite(text, raw, got.path, function(st){
    var containerKey = st.panels && typeof st.panels === 'object' && !Array.isArray(st.panels) ? 'panels' :
      st.patch && typeof st.patch === 'object' && !Array.isArray(st.patch) ? 'patch' : 'panels';
    var panels = Object.assign(Object.create(null), st[containerKey] || {});
    var patch = Object.assign(Object.create(null), panels[panelId] || {});
    if (value === undefined) delete patch[key]; else patch[key] = value;
    if (Object.keys(patch).length) panels[panelId] = patch; else delete panels[panelId];
    if (Object.keys(panels).length) st[containerKey] = panels; else delete st[containerKey];
  });
}

function planStepSetPanelPatch(text, raw, sectionIdx, stepIdx, panelId, patchText){
  /* replace one panel patch with operator-supplied JSON (an object) */
  var got = builderStepAt(raw, sectionIdx, stepIdx);
  if (!got) return {error: 'step not found — reselect and try again'};
  var patch;
  try { patch = JSON.parse(patchText); }
  catch (ex){ return {error: 'the patch is not valid JSON (' + ex.message + ')'}; }
  if (!patch || typeof patch !== 'object' || Array.isArray(patch))
    return {error: 'a panel patch is a JSON object'};
  if (!(got.st.panels && Object.prototype.hasOwnProperty.call(got.st.panels, panelId)))
    return {error: 'panel "' + panelId + '" is not in this step'};
  return builderRewrite(text, raw, got.path.concat(['panels', panelId]), function(copy, _unused){
    /* builderRewrite mutates a copy in place; replace all fields */
    Object.keys(copy).forEach(function(k){ delete copy[k]; });
    Object.keys(patch).forEach(function(k){ copy[k] = patch[k]; });
  });
}

/* Values always come from the engine's fold. Provenance describes authored
   assignments or operation inputs; it never implements a second reducer. */
function builderEffectivePanelStates(d, stepIndex, pathId){
  if(d && d.paths){
    var route=diagramPathList(d).find(function(p){return p.id===pathId && p.indices.indexOf(stepIndex)>=0;}) ||
      diagramPathList(d).find(function(p){return p.indices.indexOf(stepIndex)>=0;});
    if(!route) return {error:'This step is not part of a path.'};
    d=diagramForPath(d,route.id);stepIndex=route.indices.indexOf(stepIndex);
  }
  if (!d || !Array.isArray(d.steps) || !Number.isInteger(stepIndex) || stepIndex<0 || stepIndex>=d.steps.length)
    return {error:'Select an existing step to inspect its effective state.'};
  var panels=Array.isArray(d.panels)?d.panels:[], seen=new Set(), folded;
  if (panels.some(function(p){ if (!p || typeof p.id!=='string' || !p.id || seen.has(p.id)) return true; seen.add(p.id); return false; }))
    return {error:'Use unique non-empty string panel IDs; fix missing or duplicate IDs before inspecting effective state.'};
  try { folded=foldPanelStates(d); } catch(ex){ return {error:'Unable to fold panel state. Fix the diagram validation errors first.'}; }
  try {
    panels.forEach(function(p){ JSON.stringify((folded[p.id]||[])[stepIndex],function(key,value){
      if (typeof value==='number' && !Number.isFinite(value)) throw new Error('non-finite');
      return value;
    }); });
  } catch(ex){ return {error:'Effective state contains non-finite or unsupported values. Fix validation errors before inspecting its JSON.'}; }
  var own=function(o,k){ return o!=null && Object.prototype.hasOwnProperty.call(o,k); };
  return {panels:panels.map(function(p,pi){
    var snapshot=(folded[p.id]||[])[stepIndex]||{};
    function input(i,key,once){
      var patchKey=i==null?null:(d.steps[i].panels && typeof d.steps[i].panels==='object' && !Array.isArray(d.steps[i].panels)?'panels':'patch');
      var path=i==null?['panels',pi,'initial']:['steps',d._sourceIndices ? d._sourceIndices[i] : i,patchKey,p.id];
      if (once) path.push('enterOnce'); path.push(key);
      return {step:i,key:key,path:path,label:(i==null?'Initial':('Step '+(i+1)))+(once?' · enterOnce':'')+' · '+key};
    }
    function history(keys,includeInitial,label){
      var inputs=[];
      if (includeInitial) keys.forEach(function(key){ if (own(p.initial,key)) inputs.push(input(null,key,false)); });
      for (var i=0;i<=stepIndex;i++){
        var patch=(stepPanelPatch(d.steps[i])||{})[p.id];
        keys.forEach(function(key){ if (own(patch,key)) inputs.push(input(i,key,false)); });
      }
      return {kind:inputs.length?'history':'engine',label:inputs.length?label:'Engine default',inputs:inputs};
    }
    function assignment(key,accept,allowOnce,preserveInitial){
      var source=own(p.initial,key) && (preserveInitial||!accept||accept(p.initial[key]))?input(null,key,false):null;
      for(var i=0;i<=stepIndex;i++){
        var patch=(stepPanelPatch(d.steps[i])||{})[p.id];
        if (own(patch,key) && (!accept||accept(patch[key]))) source=input(i,key,false);
      }
      var current=(stepPanelPatch(d.steps[stepIndex])||{})[p.id];
      if (allowOnce && own(current && current.enterOnce,key))
        return {kind:'transient',label:'This step only · enterOnce',inputs:[input(stepIndex,key,true)]};
      return source?{kind:source.step==null?'initial':source.step===stepIndex?'step':'inherited',
        label:source.step==null?'Initial state':source.step===stepIndex?'Set at this step':'Inherited from step '+(source.step+1),inputs:[source]}:
        {kind:'engine',label:'Engine default',inputs:[]};
    }
    function origin(key){
      if (p.type === 'homemap'){
        if (key === 'signals'){
          var signalPatch = (stepPanelPatch(d.steps[stepIndex]) || {})[p.id];
          return own(signalPatch, key) ? {kind:'transient', label:'This step only', inputs:[input(stepIndex,key,false)]} :
            {kind:'engine', label:'No signals at this step', inputs:[]};
        }
        var subject = homemapSubjects(p).some(function(s){ return s.id === key; });
        return assignment(key, subject ? function(v){ return v === null || homemapSubjectPosition(v); } : null, false);
      }
      if (p.type==='inflight'){
        if (key==='bars') return history(['start','end','mark'],false,'Computed start/end/mark history');
        return {kind:'engine',label:key==='currentStep'?'Engine · current step':'Engine · total steps',inputs:[]};
      }
      if (p.type==='phone'){
        if (key==='notifications') return history(['notify','clear'],true,'Computed notification history');
        if (key==='clock') return assignment(key,function(v){ return typeof v==='string'; },false);
        return {kind:'engine',label:'Engine · presentation metadata',inputs:[]};
      }
      if (key==='log') return history(['log'],true,'Accumulated log history');
      if (p.type==='timeline' && (key==='events'||key==='miss')) return history([key],true,'Accumulated '+key+' history');
      var current=(stepPanelPatch(d.steps[stepIndex])||{})[p.id];
      if (own(current && current.enterOnce,key)) return assignment(key,null,true);
      if (key==='mark'||key==='cells') return history(['cells','mark'],true,'Computed cells/mark history');
      return assignment(key,p.type==='timeline' && key==='now'?function(v){ return parseClock(v)!=null; }:null,true,true);
    }
    return {id:p.id,type:p.type,title:p.title||p.id,index:pi,state:snapshot,
      fields:Object.keys(snapshot).sort().map(function(key){ return {key:key,value:snapshot[key],origin:origin(key)}; })};
  })};
}

/* ---------------- panel setup fields ----------------
   One row of typed controls per setup field of each widget type.
   Kinds: text | num | csv (comma-separated string list) | scene (token
   select) | json (an object, edited as JSON) | jsonArr (an array,
   edited as JSON). Structural fields stay JSON-in-place — their shapes
   differ too much per widget for typed sub-forms — but every declared
   field is exposed. tests assert the table covers exactly the engine's
   PANEL_TYPES and every key the insert palette's starter templates
   carry. */

/* Setup-field control kinds:
   text / num / csv / scene keep their original meaning; json / jsonArr /
   jsonAny are raw textareas. New typed kinds (each still offers a raw-JSON
   fallback in the form):
     clock — duration string validated by the bundle's parseClock when present
     map   — {key: value} object edited as key/value rows (colors, tags)
     rows  — array of objects edited as one input row per item; the shape
             (third tuple element) lists cols [{k, kind?, req?, options?}]
             and an optional max; unknown keys on existing items survive edits
     objf  — one fixed-shape object edited inline (timeline cadence) */
var PANEL_SETUP_FIELDS = {
  replicas:  [['unit','text'],['replicas','rows',{cols:[{k:'id',req:true},{k:'label'}],max:8}],['initial','json']],
  trace:     [['spans','json'],['initial','json']],
  table:     [['columns', 'rows', {cols: [{k: 'id', req: true}, {k: 'label'}], max: 4}], ['initial', 'json']],
  checks:    [['checks', 'rows', {cols: [{k: 'id', req: true}, {k: 'label'}], max: 12}], ['initial', 'json']],
  budget:    [['metrics', 'rows', {cols: [{k: 'id', req: true}, {k: 'label'}, {k: 'unit'},
                {k: 'max', kind: 'num', req: true}, {k: 'warn', kind: 'num'}], max: 6}], ['initial', 'json']],
  state:     [['states', 'csv'], ['colors', 'map'], ['initial', 'json']],
  leds:      [['leds', 'rows', {cols: [{k: 'id', req: true}, {k: 'label'}]}], ['initial', 'json']],
  gauge:     [['unit', 'text'], ['max', 'num'], ['initial', 'json']],
  log:       [['tags', 'map'], ['initial', 'json']],
  screen:    [['scene', 'scene'], ['initial', 'json']],
  waterfall: [['spans', 'rows', {cols: [{k: 'id', req: true}, {k: 'label'}, {k: 'ms', kind: 'num', req: true}, {k: 'startMs', kind: 'num'}]}],
              ['initial', 'json']],
  orbit:     [['states', 'csv'], ['colors', 'map'], ['initial', 'json']],
  zoneframe: [['zones', 'jsonArr'], ['initial', 'json']],
  xray:      [['layers', 'rows', {cols: [{k: 'id', req: true}, {k: 'label'}, {k: 'holder'}]}], ['initial', 'json']],
  queue:     [['initial', 'json']],
  pir:       [['cone', 'json'], ['sensor', 'json'], ['path', 'jsonArr'], ['initial', 'json']],
  thermo:    [['unit', 'text'], ['min', 'num'], ['max', 'num'], ['warn', 'num'], ['crit', 'num'], ['initial', 'json']],
  battery:   [['low', 'num'], ['crit', 'num'], ['initial', 'json']],
  buffer:    [['segments', 'num'], ['capacity', 'text'], ['initial', 'json']],
  radar:     [['sensor', 'json'], ['facing', 'num'], ['spread', 'num'], ['range', 'num'],
              ['threshold', 'num'], ['rings', 'jsonAny'], ['scale', 'json'],
              ['zones', 'jsonArr'], ['initial', 'json']],
  homemap:   [['outline', 'objf', {cols:[{k:'w',kind:'num',label:'Width'}, {k:'h',kind:'num',label:'Height'},
                {k:'x',kind:'num',label:'Left (auto)'}, {k:'y',kind:'num',label:'Top (auto)'}],
                hint:'Floor plan: width 20–320, height 20–180. Blank left/top centers the house. Rooms and devices keep their coordinates. Press Enter or leave a field to save.'}], ['rooms', 'rows', {cols: [
                {k:'label'}, {k:'kind',kind:'enum',options:['room','outdoor']}, {k:'x', kind:'num', req:true}, {k:'y', kind:'num', req:true},
                {k:'w', kind:'num', req:true}, {k:'h', kind:'num', req:true}]}], ['devices', 'rows', {cols: [
                {k: 'id', req: true}, {k: 'kind', kind: 'enum', options: ['camera', 'entry', 'sensor', 'hub']},
                {k: 'display', kind: 'enum', options: ['marker', 'door']},
                {k: 'label'}, {k: 'x', kind: 'num', req: true}, {k: 'y', kind: 'num', req: true},
                {k: 'facing', kind: 'num'}, {k: 'spread', kind: 'num'}, {k: 'range', kind: 'num'}, {k: 'icon'},
                {k: 'doorWidth', kind: 'num'}, {k: 'doorSwing', kind: 'num'}],
              max: 12}], ['subjects', 'rows', {cols: [
                {k: 'id', req: true}, {k: 'label'}, {k: 'x', kind: 'num', req: true},
                {k: 'y', kind: 'num', req: true}, {k: 'icon'}], max: 6}], ['initial', 'json']],
  signal:    [['links', 'rows', {cols: [{k: 'id', req: true}, {k: 'label'},
                {k: 'transport', kind: 'enum',
                 options: ['wifi', 'subghz', 'thread', 'zigbee', 'zwave', 'cellular', 'poe', 'ethernet', 'ble']}],
              max: 6}], ['initial', 'json']],
  tiles:     [['tiles', 'rows', {cols: [{k: 'id', req: true}, {k: 'label'}], max: 12}],
              ['states', 'csv'], ['colors', 'map'], ['initial', 'json']],
  inflight:  [['lanes', 'rows', {cols: [{k: 'id', req: true}, {k: 'label'}]}], ['initial', 'json']],
  phone:     [['brand', 'objf', {cols: [{k: 'app'}, {k: 'logo'}, {k: 'accent'}, {k: 'bg'}, {k: 'fg'}]}],
              ['initial', 'json']],
  timeline:  [['span', 'clock'],
              ['cadence', 'objf', {cols: [{k: 'every', kind: 'clock', req: true}, {k: 'label'}]}],
              ['lanes', 'rows', {cols: [{k: 'id', req: true}, {k: 'label'},
                {k: 'every', kind: 'clock', req: true}], max: 4}],
              ['events', 'rows', {cols: [{k: 'at', kind: 'clock', req: true}, {k: 'label'},
                {k: 'kind', kind: 'enum', options: ['ok', 'alert', 'info']}, {k: 'lane'}]}],
              ['initial', 'json']]
};

/* Dynamic-key types are expanded from their declarations by panelPatchFields. */
var PANEL_PATCH_FIELDS = {
  replicas:  [['reference','json'],['replicas','json'],['note','text']],
  trace:     [['selected','text']],
  table:     [['rows', 'jsonArr'], ['note', 'text']],
  checks:    [['results', 'json'], ['note', 'text']],
  budget:    [['values', 'json'], ['note', 'text']],
  state:     [['state', 'text']],
  leds:      [],
  gauge:     [['value', 'num']],
  log:       [['log', 'jsonArr']],
  screen:    [['mode', 'enum', ['off', 'boot', 'live', 'rec', 'save']],
              ['scenePlayback', 'enum', ['waiting', 'playing']], ['banner', 'text']],
  waterfall: [['reveal', 'num'], ['highlight', 'text'], ['total', 'text']],
  orbit:     [['state', 'text'], ['via', 'text']],
  zoneframe: [['zones', 'jsonArr'], ['subject', 'json'],
              ['verdict', 'enum', ['alert', 'suppress', 'never-captured']]],
  xray:      [['layers', 'jsonArr'], ['hop', 'text']],
  queue:     [['state', 'enum', ['empty', 'enqueue', 'held', 'dequeue']], ['label', 'text'],
              ['from', 'text'], ['to', 'text'], ['reason', 'text']],
  pir:       [['subject', 'json'], ['tripped', 'bool'], ['status', 'text'], ['banner', 'text']],
  thermo:    [['value', 'num'], ['label', 'text']],
  battery:   [['charge', 'num'], ['trend', 'enum', ['charging', 'draining', 'idle']],
              ['source', 'enum', ['solar', 'wired', 'poe', 'cells']], ['cold', 'bool'],
              ['note', 'text'], ['label', 'text']],
  buffer:    [['cells', 'jsonArr'], ['mark', 'jsonArr'], ['head', 'num'], ['note', 'text'], ['label', 'text']],
  radar:     [['subject', 'json'], ['threshold', 'num'], ['alert', 'bool'], ['status', 'text'], ['banner', 'text']],
  homemap:   [['signals', 'jsonArr']],
  signal:    [],
  tiles:     [],
  inflight:  [['start', 'jsonArr'], ['end', 'jsonArr'], ['mark', 'jsonArr']],
  phone:     [['clock', 'text'], ['notify', 'jsonAny'], ['clear', 'bool', {trueOnly: true}]],
  timeline:  [['now', 'clock'], ['events', 'jsonArr'], ['miss', 'jsonArr']]
};
var OPEN_PATCH_EDITORS = new Set();
var OPEN_EFFECTIVE_STATE = false;
var OPEN_EFFECTIVE_PANELS = new Set();

function patchSummaryLine(patchObj){
  var keys = Object.keys(patchObj || {}).slice(0, 2);
  if (!keys.length) return 'empty patch';
  return keys.map(function(key){
    var value = patchObj[key];
    var compact = Array.isArray(value) ? '[' + value.length + ' items]' :
      value !== null && typeof value === 'object' ? '{…}' : String(value);
    return key + ' → ' + compact;
  }).join(' · ');
}

function panelPatchFields(decl){
  if (!decl || !Object.prototype.hasOwnProperty.call(PANEL_PATCH_FIELDS, decl.type)) return null;
  var states = Array.isArray(decl.states) ? decl.states.map(String) : [];
  var stateField = states.length ? ['state', 'enum', states] : ['state', 'text'];
  if (decl.type === 'homemap'){
    var vocab = {camera: ['sleep', 'scan', 'detect', 'rec', 'off'], entry: ['closed', 'open', 'alert'],
      sensor: ['ok', 'warn', 'alert', 'off'], hub: ['idle', 'rx', 'tx', 'alert']};
    var seen = Object.create(null);
    var fields = (Array.isArray(decl.devices) ? decl.devices : []).filter(function(d){
      if (!d || typeof d.id !== 'string' || !d.id || seen[d.id]) return false;
      seen[d.id] = true;
      return d.id !== 'signals' && typeof d.kind === 'string' && Object.prototype.hasOwnProperty.call(vocab, d.kind) &&
        typeof d.x === 'number' && isFinite(d.x) && typeof d.y === 'number' && isFinite(d.y);
    }).map(function(d){ return [d.id, 'enum', vocab[d.kind]]; });
    (Array.isArray(decl.subjects) ? decl.subjects : []).forEach(function(sub){
      if (!sub || typeof sub.id !== 'string' || !sub.id || seen[sub.id]) return;
      seen[sub.id] = true;
      if (sub.id === 'signals' || typeof sub.x !== 'number' || !isFinite(sub.x) ||
          typeof sub.y !== 'number' || !isFinite(sub.y)) return;
      fields.push([sub.id, 'json', {nullable: true}]);
    });
    return fields.concat([['signals', 'jsonArr']]);
  }
  if (decl.type === 'state') return [stateField];
  if (decl.type === 'orbit') return [stateField, ['via', 'text']];
  if (['leds', 'tiles', 'signal'].indexOf(decl.type) >= 0){
    var ids = decl[decl.type === 'signal' ? 'links' : decl.type];
    return (Array.isArray(ids) ? ids : []).filter(function(item){
      return item && typeof item.id === 'string' && item.id !== '';
    }).map(function(item){
      if (decl.type === 'leds') return [item.id, 'enum', ['on', 'off', 'tx', 'rx']];
      return [item.id, 'objf', decl.type === 'tiles' ? [stateField, ['sub', 'text']] :
        [['state', 'enum', ['ok', 'weak', 'retrying', 'lost', 'jammed']],
         ['bars', 'num', {min: 0, max: 4}], ['note', 'text']]];
    });
  }
  return PANEL_PATCH_FIELDS[decl.type];
}

/* Collect only the supplied fields. Blank values omit keys; callers merge
   at the patch level, but dynamic tile/link objects replace wholesale. */
function patchFieldsCollect(fields, values){
  var item = Object.create(null);
  for (var i = 0; i < fields.length; i++){
    var f = fields[i], key = f[0], kind = f[1], extra = f[2];
    var raw = !Object.prototype.hasOwnProperty.call(values, key) || values[key] == null ? '' : String(values[key]);
    if (kind !== 'enum') raw = raw.trim();
    if (raw === '') continue;
    var value = raw;
    if (kind === 'num'){
      value = Number(raw);
      if (!isFinite(value)) return {error: key + ': "' + raw + '" is not a number'};
      if (extra && (value < extra.min || value > extra.max))
        return {error: key + ': use a number from ' + extra.min + ' to ' + extra.max};
    } else if (kind === 'bool'){
      if (raw !== 'true' && raw !== 'false') return {error: key + ': use true or false'};
      /* the validator accepts only literal true for phone clear — false is
         an always-warned no-op, so the form refuses to write it */
      if (extra && extra.trueOnly && raw === 'false')
        return {error: key + ': only true (or unset) — false is ignored by the renderer'};
      value = raw === 'true';
    } else if (kind === 'clock' && builderClockInvalid(raw)){
      return {error: key + ': "' + raw + '" is not ' + BUILDER_CLOCK_HINT};
    } else if (kind === 'json' || kind === 'jsonArr' || kind === 'jsonAny'){
      try { value = JSON.parse(raw); }
      catch (ex){ return {error: key + ': not valid JSON (' + ex.message + ')'}; }
      if (kind === 'jsonArr' && !Array.isArray(value)) return {error: key + ' is a JSON array — [ ... ]'};
      if (kind === 'json' && !(value === null && extra && extra.nullable) &&
          (!value || typeof value !== 'object' || Array.isArray(value)))
        return {error: key + ' is a JSON object' + (extra && extra.nullable ? ' or null' : '') + ' — { ... }'};
    }
    item[key] = value;
  }
  return {item: item};
}

var SCENE_TOKENS = ['person-at-door-night', 'person-through-door', 'doorbell-run-away', 'doorbell-runners', 'package-drop', 'kitchen-fire', 'static-noise'];

/* A local preview never patches camera mode or advances the story. Replay
   replaces only this SVG, so it cannot reset the diagram's animation. */
function screenScenePreview(initialScene){
  var wrap = document.createElement('div'); wrap.className = 'screen-scene-preview';
  var box = document.createElement('div'); box.className = 'screenbox m-live';
  box.setAttribute('role', 'img'); wrap.appendChild(box);
  var foot = document.createElement('div'); foot.className = 'screen-scene-footer';
  var note = document.createElement('span'); note.className = 'fnote'; note.textContent = 'Simulated clip preview';
  var replay = document.createElement('button'); replay.type = 'button'; replay.className = 'bbtn';
  replay.textContent = 'Replay clip';
  foot.appendChild(note); foot.appendChild(replay); wrap.appendChild(foot);
  var selected;
  function setScene(scene){
    selected = SCENE_TOKENS.indexOf(scene) >= 0 ? scene : 'static-noise';
    box.innerHTML = SCENES[selected];
    box.setAttribute('aria-label', SCENE_LABELS[selected] + ' — simulated clip preview');
  }
  replay.addEventListener('click', function(){ setScene(selected); });
  setScene(initialScene);
  return {element:wrap, setScene:setScene};
}

/* parseClock rides in the same bundle (validator.js); the vm-loaded test
   copy of this file has no validator, so capture defensively. */
var BUILDER_CLOCK_PARSE = typeof parseClock === 'function' ? parseClock : null;
var BUILDER_CLOCK_HINT = 'a duration like 90s, 5m, 2h30m';

function builderClockInvalid(text){
  return !!(BUILDER_CLOCK_PARSE && typeof text === 'string' && text.trim() !== '' &&
            BUILDER_CLOCK_PARSE(text) == null);
}

/* Merge one edited row into its original item: edited cols overwrite or
   delete keys; keys the editor does not know about survive untouched. */
function builderRowMerge(shape, base, values){
  var item = {};
  Object.keys(base || {}).forEach(function(k){ item[k] = base[k]; });
  var error = null;
  (shape.cols || []).forEach(function(col){
    if (error) return;
    var raw = values && typeof values[col.k] === 'string' ? values[col.k].trim() : '';
    if (raw === ''){
      if (col.req){ error = col.k + ' is required'; return; }
      delete item[col.k];
      return;
    }
    if (col.kind === 'num'){
      var num = Number(raw);
      if (!isFinite(num)){ error = col.k + ': "' + raw + '" is not a number'; return; }
      item[col.k] = num;
      return;
    }
    if (col.kind === 'clock' && builderClockInvalid(raw)){
      error = col.k + ': "' + raw + '" is not ' + BUILDER_CLOCK_HINT; return;
    }
    /* an unknown enum value already ON the item passes through unchanged —
       editing a sibling column must never delete or reject it */
    if (col.kind === 'enum' && (col.options || []).indexOf(raw) < 0 &&
        !(base && base[col.k] === raw)){
      error = col.k + ': "' + raw + '" is not one of ' + (col.options || []).join(' | '); return;
    }
    item[col.k] = raw;
  });
  return error ? {error: error} : {item: item};
}

/* rows: [{base: originalItem|null, values: {colKey: rawString}}] in display
   order. Fully-empty NEW rows are dropped; empty EXISTING rows are kept and
   fail their required columns (deleting is the ✕ button's job, not blanking). */
function rowsEditorCollect(shape, rows){
  var items = [];
  for (var i = 0; i < (rows || []).length; i++){
    var row = rows[i];
    var blank = (shape.cols || []).every(function(col){
      var raw = row.values && typeof row.values[col.k] === 'string' ? row.values[col.k].trim() : '';
      return raw === '';
    });
    if (blank && !row.base) continue;
    var merged = builderRowMerge(shape, row.base, row.values);
    if (merged.error) return {error: 'item ' + (i + 1) + ': ' + merged.error};
    items.push(merged.item);
  }
  if (shape.max && items.length > shape.max)
    return {error: 'at most ' + shape.max + ' items (' + items.length + ' given)'};
  return {items: items};
}

/* pairs: [{key: rawString, value: rawString}] -> plain object or null when
   nothing is left. Blank keys drop the pair; duplicate keys are an error. */
function mapEditorCollect(pairs){
  var obj = {}, count = 0;
  for (var i = 0; i < (pairs || []).length; i++){
    var key = typeof pairs[i].key === 'string' ? pairs[i].key.trim() : '';
    var value = typeof pairs[i].value === 'string' ? pairs[i].value.trim() : '';
    if (key === '') continue;
    if (Object.prototype.hasOwnProperty.call(obj, key))
      return {error: 'duplicate key "' + key + '"'};
    if (value === '') continue;
    obj[key] = value;
    count++;
  }
  return {obj: count ? obj : null};
}

/* one fixed-shape object (timeline cadence): all-empty means remove the
   field entirely; otherwise the same column rules as rows apply. */
function objFieldsCollect(shape, base, values){
  var blank = (shape.cols || []).every(function(col){
    var raw = values && typeof values[col.k] === 'string' ? values[col.k].trim() : '';
    return raw === '';
  });
  if (blank) return {obj: null};
  var merged = builderRowMerge(shape, base, values);
  return merged.error ? {error: merged.error} : {obj: merged.item};
}

/* ---------------- per-element authoring guidance ---------------- */

