  /* ================= multi-select (shift/ctrl/cmd-click) ================= */
  var multiSel = [];
  var multiSurvive = false; /* set by builder-internal renders; a render
     WITHOUT it (Render button, hand-pasted source) clears the set —
     coinciding identities in replaced content must never stay selected */
  /* the flag is consumed by the mutation observer — but a builder render
     that FAILS validation mutates nothing and would leave it stale, so an
     explicit user render request invalidates it first (capture phase runs
     before boot's own Render handler) */
  (function(){
    var goBtn = document.getElementById('go');
    if (goBtn) goBtn.addEventListener('click', function(){ multiSurvive = false; }, true);
  })();
  function multiIdent(t){
    return t.section + '|' + t.kind + '|' + (t.kind === 'node' ? t.id : t.index);
  }
  function clearMultiSelect(){
    multiSel.forEach(function(t){ if (t.el && t.el.classList) t.el.classList.remove('dv-sel'); });
    multiSel = [];
  }
  function dropMultiUI(){
    if (guide) guide.hidden = true;
    retireInspector();
  }
  /* after a re-render the selected elements are new DOM: re-resolve each
     identity, drop the ones that no longer exist, re-ring the rest */
  function reapplyMultiSel(){
    if (!multiSel.length) return;
    multiSel = multiSel.filter(function(t){
      var el = findTargetEl(t);
      if (!el) return false;
      t.el = el;
      el.classList.add('dv-sel');
      return true;
    });
    if (!multiSel.length) dropMultiUI();
    else renderMultiInspector();
  }
  function toggleMultiSelect(target){
    if (BUILDER_MULTI_KINDS.indexOf(target.kind) < 0){
      inspectorMessage('multi-select supports nodes, edges, steps, panels, bullets, and contract rows');
      return;
    }
    if (multiSel.length && multiSel[0].kind !== target.kind){
      inspectorMessage('multi-select holds ' + multiSel[0].kind + 's — Esc clears it, then start over');
      return;
    }
    /* a mismatched modifier-click against an existing SINGLE selection is
       refused the same way — it must leave that selection standing, never
       silently replace it */
    if (!multiSel.length && currentTarget && currentTarget.kind !== target.kind){
      inspectorMessage('multi-select works within one kind — the current selection is a ' +
        currentTarget.kind + '; plain-click to switch');
      return;
    }
    /* a shift-click after a plain click grows the pair naturally: seed the
       set with the current single selection when the kinds match. The
       single-selection ring is dropped FIRST — the seed then re-rings the
       same element as a multi member. */
    var prev = currentTarget;
    currentTarget = null;
    setSelected(null);
    if (!multiSel.length && prev && prev.kind === target.kind &&
        multiIdent(prev) !== multiIdent(target)){
      var seedEl = findTargetEl(prev);
      if (seedEl){
        multiSel.push({section: prev.section, kind: prev.kind,
                       id: prev.id, index: prev.index, el: seedEl});
        seedEl.classList.add('dv-sel');
      }
    }
    var key = multiIdent(target), existing = -1;
    multiSel.forEach(function(t, i){ if (multiIdent(t) === key) existing = i; });
    if (existing >= 0){
      var gone = multiSel.splice(existing, 1)[0];
      if (gone.el && gone.el.classList) gone.el.classList.remove('dv-sel');
    } else {
      multiSel.push({section: target.section, kind: target.kind,
                     id: target.id, index: target.index, el: target.el});
      if (target.el && target.el.classList) target.el.classList.add('dv-sel');
    }
    if (!multiSel.length){ dropMultiUI(); return; }
    if (multiSel.length === 1){
      /* one left: collapse back to an ordinary single selection */
      var only = multiSel[0];
      clearMultiSelect();
      selectTarget({section: only.section, kind: only.kind, id: only.id,
                    index: only.index, el: only.el}, false);
      return;
    }
    if (opts.workspace) opts.workspace.showTool('inspect', {closeUtilities:true});
    renderMultiInspector();
  }
  function applyBulkField(key, valueTextOrNull){
    var plan = planBulkSetField(src.value, multiSel, key, valueTextOrNull);
    return applyPlan(plan); /* the re-render observer re-rings + re-renders the multi form */
  }
  function bulkDeleteSelected(){
    var n = multiSel.length, kind = multiSel[0].kind;
    var plan = planBulkDelete(src.value, multiSel);
    if (applyPlan(plan)){
      clearMultiSelect();
      inspectorMessage(n + ' ' + kind + (n > 1 ? 's' : '') + ' deleted — undo restores them');
    }
  }
  function renderMultiInspector(){
    if (!guide || multiSel.length < 2) return;
    revealInspector();
    guide.hidden = false;
    guide.innerHTML = '';
    var kind = multiSel[0].kind;
    var head = document.createElement('b');
    head.textContent = multiSel.length + ' ' + kind + 's selected';
    guide.appendChild(head);
    var p = document.createElement('span');
    p.className = 'gpath';
    p.textContent = 'shift-click adds/removes · Esc clears';
    guide.appendChild(p);
    var err = document.createElement('div');
    err.className = 'gerr ierr'; err.hidden = true;
    guide.appendChild(err);
    var form = document.createElement('div');
    form.className = 'iform';
    /* every control writes the SAME value to every selected element;
       an empty value removes the field from all of them */
    if (kind === 'node'){
      var parsed = parseEditor();
      var values = [], diagrams = [];
      if (!parsed.error) multiSel.forEach(function(t){
        var got = builderDiagram(src.value, parsed.raw, t.section);
        if (!got.error){
          diagrams.push(got.d);
          values.push(((got.d.nodes || {})[t.id] || {}).group || '');
        }
      });
      ensureGroupDatalist(diagrams);
      var mixed = values.some(function(v){ return v !== values[0]; });
      form.appendChild(frow('group', groupControl(mixed ? null : values[0], function(v){
        return commitGroup(function(raw){ return planBulkSetGroup(src.value, raw, multiSel, v); });
      }, {placeholder: mixed ? 'mixed — empty removes' : 'group key — empty removes', commitUnchanged: mixed})));
      form.appendChild(frow('tint', selectControl(['cmd', 'auth', 'data', 'mqtt', 'dev'], null, function(v){
        return applyBulkField('tint', v == null ? null : JSON.stringify(v));
      }, true)));
      form.appendChild(frow('icon', selectControl(
        ICON_SET, null, function(v){
        return applyBulkField('icon', v == null ? null : JSON.stringify(v));
      }, true)));
    }
    if (kind === 'edge'){
      form.appendChild(frow('kind', textControl(null, function(v){
        return applyBulkField('kind', v == null ? null : JSON.stringify(v));
      }, {placeholder: 'https | int | mqtt | declared protocol'})));
      form.appendChild(frow('ret', checkboxControl(false, function(on){
        return applyBulkField('ret', on ? 'true' : null);
      })));
    }
    if (kind === 'step'){
      form.appendChild(frow('lane', textControl(null, function(v){
        return applyBulkField('lane', v == null ? null : JSON.stringify(v));
      }, {placeholder: 'lane id from page.lanes — empty removes'})));
    }
    if (form.childNodes.length) guide.appendChild(form);
    var acts = document.createElement('div');
    acts.className = 'iacts';
    if(objectClipboard && (kind === 'node' || kind === 'panel')){
      acts.appendChild(actionButton('Copy selected',function(){objectClipboard.copy(multiSel);}));
      acts.appendChild(actionButton('Duplicate selected',function(){objectClipboard.duplicate(multiSel);}));
    }
    if (kind === 'node' || kind === 'edge' || kind === 'step'){
      acts.appendChild(actionButton('mark delta', function(){ return applyBulkField('delta', 'true'); }));
      acts.appendChild(actionButton('clear delta', function(){ return applyBulkField('delta', null); }));
    }
    if (kind === 'node'){
      acts.appendChild(actionButton('stack together', function(){
        var secs = {};
        multiSel.forEach(function(t){ secs[t.section] = true; });
        if (Object.keys(secs).length !== 1){
          formError('stacking needs nodes from a single section');
          return;
        }
        var sec = multiSel[0].section;
        var ids = multiSel.map(function(t){ return t.id; });
        commitGroup(function(raw){ return planStackNodes(src.value, raw, sec, ids); });
      }));
    }
    acts.appendChild(actionButton('delete ' + multiSel.length + ' ' + kind + 's',
      bulkDeleteSelected, 'bdanger'));
    guide.appendChild(acts);
  }

  function renderInspector(){
    invalidateEffectiveState=null;
    hideDiff();
    if (!guide || !currentTarget) return;
    var t = currentTarget;
    /* wiping the content clamps the .guide scroll box to the top, so a
       form refresh after a control commit jumped the inspector. Keep the
       scroll position when re-rendering the SAME element; a new
       selection still starts at the top. */
    var targetKey = JSON.stringify([t.kind, t.section, t.id, t.index, t.block, t.tab]);
    var keepScroll = targetKey === inspectorScrollKey ? guide.scrollTop : null;
    inspectorScrollKey = targetKey;
    revealInspector();
    guide.hidden = false;
    guide.innerHTML = '';
    var g = BUILDER_GUIDES[t.kind] || {title: t.kind, how: '', fields: []};

    var head = document.createElement('b');
    head.textContent = g.title;
    guide.appendChild(head);

    var parsed = parseEditor();
    var path = parsed.error ? null : builderTargetPath(parsed.raw, t);
    var loc = path ? jsonLocate(src.value, path) : null;

    var p = document.createElement(loc ? 'button' : 'span');
    p.className = 'gpath';
    p.textContent = path ? builderPathString(path) + (loc ? ' ↗ JSON' : '') : '';
    if (loc){
      var sourceAtSelection = src.value;
      p.type = 'button'; p.setAttribute('aria-label', 'Show selected element in JSON');
      p.addEventListener('click', function(){
        if (src.value !== sourceAtSelection){ formError('Source changed. Click Render and reselect this element.'); return; }
        selectRange(loc, true);
      });
    }
    guide.appendChild(p);

    var posText = parsed.error ? null : builderPositionLine(parsed.raw, t);
    if (posText){
      var pos = document.createElement('span');
      pos.className = 'gpos';
      pos.textContent = posText;
      guide.appendChild(pos);
    }

    var err = document.createElement('div');
    err.className = 'gerr ierr'; err.hidden = true;
    guide.appendChild(err);

    if (parsed.error){
      formError(parsed.error + ' — fix it to edit this element');
    } else if (!loc && !(t.kind === 'group' && !builderDiagram(src.value, parsed.raw, t.section).error)){
      formError('definition not found in the editor text — the render and the editor may be out of sync (click Render)');
    } else if (t.kind === 'section' && path.length === 0){
      formError('bare diagram — wrap it as {"page": {"blocks": [ ... ]}} to edit heading and accent');
    } else {
      var val = path ? specValueAt(parsed.raw, path) : {};
      if (val == null) val = {};
      var rec = specSectionPaths(parsed.raw)[t.section];
      var ctx = {
        page: normalize(parsed.raw) || {},
        diagram: rec ? specValueAt(parsed.raw, rec.diagram) : null
      };
      if (t.kind === 'step' && ctx.diagram && ctx.diagram.paths){
        var sharing = diagramPathList(ctx.diagram).filter(function(route){return route.indices.indexOf(t.index) >= 0;});
        if (sharing.length > 1){
          var sharedNote = document.createElement('p'); sharedNote.className = 'fnote shared-step-note';
          sharedNote.textContent = 'Shared step — edits apply to: ' + sharing.map(function(route){return route.label;}).join(', ') + '.';
          guide.appendChild(sharedNote);
          var independent = actionButton('Make independent here', function(){ if (stepList) stepList.editPathStep('independent'); });
          independent.disabled = !!addToStep || !!connect; guide.appendChild(independent);
        }
      }
      var form = document.createElement('div');
      form.className = 'iform';
      if (t.kind === 'tab') ensureAccentDatalist();
      var rows =
        t.kind === 'group' ? groupForm(val, ctx) :
        t.kind === 'node' ? nodeForm(val, ctx) :
        t.kind === 'edge' ? edgeForm(val, ctx) :
        t.kind === 'step' ? stepForm(val, ctx) :
        t.kind === 'panel' ? panelForm(val, ctx) :
        t.kind === 'bullet' ? bulletForm(val, ctx) :
        t.kind === 'para' ? paraForm(val, ctx) :
        t.kind === 'crow' ? crowForm(val, ctx) :
        t.kind === 'tab' ? tabForm(val, ctx) : sectionForm(val, ctx);
      rows.forEach(function(r){ form.appendChild(r); });
      guide.appendChild(form);

      var acts = document.createElement('div');
      acts.className = 'iacts';
      if(objectClipboard && ['node','section','panel'].indexOf(t.kind)>=0){
        acts.appendChild(actionButton('Copy '+t.kind,function(){objectClipboard.copy([t]);}));
        acts.appendChild(actionButton('Paste…',function(){clipboardHomeTarget=null;objectClipboard.open();}));
        if(t.kind === 'panel')acts.appendChild(actionButton('Duplicate panel',function(){objectClipboard.duplicate([t]);}));
      }
      if (t.kind === 'node'){
        acts.appendChild(actionButton('duplicate', function(){
          commitCascade(function(raw){ return planDuplicateNode(src.value, raw, t.section, t.id); },
            {after: function(plan){
              currentTarget = {section: t.section, kind: 'node', id: plan.id};
              renderInspector();
            }});
        }));
      }
      if (t.kind === 'section'){
        acts.appendChild(actionButton('duplicate', function(){
          commitCascade(function(raw){ return planDuplicateSection(src.value, raw, t.section); },
            {after: function(plan){
              currentTarget = {section: plan.index, kind: 'section'};
              insertSection = plan.index;
              renderInspector();
            }});
        }));
        /* the plan hands back the section's new LIST slot; the flat ordinal
           is recomputed because moving over a tabs container hops all of
           its sections at once */
        var moveSection = function(delta){
          commitCascade(function(raw){ return planMoveSection(src.value, raw, t.section, delta); },
            {after: function(plan){
              var parsed = parseEditor();
              if (!parsed.error){
                var key = JSON.stringify(plan.newPath);
                specSectionPaths(parsed.raw).forEach(function(rec, i){
                  if (JSON.stringify(rec.section) === key) t.section = i;
                });
              }
              currentTarget = {section: t.section, kind: 'section'};
              insertSection = t.section;
              rehighlight();
              renderInspector();
              flashPositionLine();
            }});
        };
        acts.appendChild(actionButton('↑ move up', function(){ moveSection(-1); }));
        acts.appendChild(actionButton('↓ move down', function(){ moveSection(1); }));
      }
      if (t.kind === 'tab'){
        acts.appendChild(actionButton('+ tab', function(){
          commitCascade(function(raw){ return planAddTab(src.value, raw, t.block, t.tab); },
            {after: function(plan){
              currentTarget = {kind: 'tab', block: plan.block, tab: plan.index};
              renderInspector();
            }});
        }));
        acts.appendChild(actionButton('← move left', function(){
          commitCascade(function(raw){ return planMoveTab(src.value, raw, t.block, t.tab, -1); },
            {after: function(plan){ t.tab = plan.index; renderInspector(); flashPositionLine(); }});
        }));
        acts.appendChild(actionButton('→ move right', function(){
          commitCascade(function(raw){ return planMoveTab(src.value, raw, t.block, t.tab, 1); },
            {after: function(plan){ t.tab = plan.index; renderInspector(); flashPositionLine(); }});
        }));
      }
      var armedHere = !!(addToStep && t.kind === 'step' &&
                         addToStep.section === t.section && addToStep.step === t.index);
      if (t.kind === 'step'){
        acts.appendChild(actionButton(armedHere ? '✕ DONE adding (Esc)' : 'ADD TO STEP', function(){
          if (addToStep){ cancelAddToStep(null); return; }
          if (connect) cancelConnect(null);
          addToStep = {section: t.section, step: t.index};
          addToStepStatus();
          renderInspector();
        }, armedHere ? 'bexit-inline' : ''));
      }
      if (t.kind === 'step' && !armedHere){
        if (ctx.diagram && ctx.diagram.paths){
          var removeHere = actionButton('Remove from this path', function(){ if (stepList) stepList.editPathStep('remove'); });
          var selectedPath = diagramPathList(ctx.diagram).find(function(p){ return p.id === (stepperFor(t.section) && stepperFor(t.section).path()); });
          removeHere.disabled = !!connect || !selectedPath || selectedPath.indices.length <= 1;
          acts.appendChild(removeHere);
        }
        acts.appendChild(actionButton('duplicate step', function(){
          commitCascade(function(raw){ return planDuplicateStep(src.value, raw, t.section, t.index, stepperFor(t.section) && stepperFor(t.section).path()); },
            {after:function(plan){ t.index = plan.index; renderInspector(); flashPositionLine(); }});
        }));
        acts.appendChild(actionButton('↑ move up', function(){
          commitCascade(function(raw){ return planMoveStep(src.value, raw, t.section, t.index, -1, stepperFor(t.section) && stepperFor(t.section).path()); },
            {after: function(plan){ t.index = plan.index; renderInspector(); flashPositionLine(); }});
        }));
        acts.appendChild(actionButton('↓ move down', function(){
          commitCascade(function(raw){ return planMoveStep(src.value, raw, t.section, t.index, 1, stepperFor(t.section) && stepperFor(t.section).path()); },
            {after: function(plan){ t.index = plan.index; renderInspector(); flashPositionLine(); }});
        }));
      }
      if (!armedHere)
        acts.appendChild(actionButton(t.kind === 'step' && ctx.diagram && ctx.diagram.paths ? 'Delete from all paths' : 'delete ' + t.kind, deleteCurrent, 'bdanger' + (t.kind === 'group' ? ' groupctl' : '')));
      guide.appendChild(acts);
    }

    /* the pass-1 field guidance, tucked under a details fold */
    var help = document.createElement('details');
    help.className = 'ihelp';
    var sum = document.createElement('summary');
    sum.textContent = 'field help';
    help.appendChild(sum);
    var how = document.createElement('div');
    how.textContent = g.how;
    help.appendChild(how);
    var ul = document.createElement('ul');
    g.fields.forEach(function(f){
      var li = document.createElement('li');
      var c = document.createElement('code');
      c.textContent = f[0];
      li.appendChild(c);
      li.appendChild(document.createTextNode(' — ' + f[1]));
      ul.appendChild(li);
    });
    help.appendChild(ul);
    if (g.tokens){
      var tok = document.createElement('div');
      tok.className = 'gtokens'; tok.textContent = g.tokens;
      help.appendChild(tok);
    }
    guide.appendChild(help);
    guide.scrollTop = keepScroll == null ? 0 : keepScroll;
  }

  /* ================= selection ================= */

  function targetFromEvent(ev){
    /* Map editing follows the same manual transport/path selection as the
       preview. Play/Pause are excluded so selecting an inspector cannot
       immediately stop a user-started animation. */
    if (!addToStep && !connect){
      var homeTarget = builderHomemapClickTarget(ev.target, stepperFor, currentTarget);
      if (homeTarget){
        if(homeTarget.kind === 'panel'){
          var marker=ev.target.closest('[data-device],[data-subject],[data-home-room]');
          if(marker)homeTarget.homeElement=marker.hasAttribute('data-device') ? {field:'devices',id:marker.getAttribute('data-device')} :
            marker.hasAttribute('data-subject') ? {field:'subjects',id:marker.getAttribute('data-subject')} : {field:'rooms',item:Number(marker.getAttribute('data-home-room'))};
        }
        return homeTarget;
      }
    }
    var transport = ev.target.closest && ev.target.closest('.tbtn');
    if (transport && /^(Previous|Next) step$/.test(transport.getAttribute('aria-label') || '') &&
        currentTarget && currentTarget.kind === 'step'){
      var activeSection = transport.closest('.doc-sec');
      if (activeSection){
        var ordinal = Number(activeSection.getAttribute('data-dv-section')), player = stepperFor(ordinal);
        if (player) return {section:ordinal, kind:'step', index:player.sourceIndex()};
      }
    }
    /* tab buttons both switch the panel (engine) and select the tab
       here; the copy chip beside a tab is NOT a .tabbtn and still falls
       through to the interactive skip below */
    var tabBtn = ev.target.closest && ev.target.closest('.tabbtn');
    if (tabBtn){
      var m = /^tab-(\d+)-(\d+)$/.exec(tabBtn.id || '');
      if (m) return {kind: 'tab', block: parseInt(m[1], 10), tab: parseInt(m[2], 10), el: tabBtn};
      return null;
    }
    /* step chips in the click-through bar both jump playback (engine)
       and select its shared source entry here, independently of its row */
    var chip = ev.target.closest && ev.target.closest('.schip');
    if (chip){
      var chipSec = chip.closest('.doc-sec');
      if (!chipSec || !chipSec.hasAttribute('data-dv-section')) return null;
      var chipIdx = Number(chip.getAttribute('data-step-source'));
      if (chipIdx < 0) return null;
      return {section: parseInt(chipSec.getAttribute('data-dv-section'), 10),
              kind: 'step', index: chipIdx, el: chip};
    }
    if (ev.target.closest('a, button, summary, [role="button"], input, select, textarea')) return null;
    /* the caption line selects the CURRENT step (links and the copy
       chip inside it were already skipped above) */
    var line = ev.target.closest && ev.target.closest('.stepline');
    if (line){
      var lineSec = line.closest('.doc-sec');
      var chipsBox = lineSec && lineSec.querySelector('.schips');
      if (!lineSec || !chipsBox || !lineSec.hasAttribute('data-dv-section')) return null;
      var cur = -1, currentChip = null;
      Array.prototype.forEach.call(chipsBox.querySelectorAll('.schip'), function(c){
        if (cur < 0 && c.getAttribute('aria-current') === 'true'){
          cur = Number(c.getAttribute('data-step-source')); currentChip = c;
        }
      });
      if (cur < 0) return null;
      return {section: parseInt(lineSec.getAttribute('data-dv-section'), 10),
              kind: 'step', index: cur, el: currentChip};
    }
    var secEl = ev.target.closest('.doc-sec');
    if (!secEl || !secEl.hasAttribute('data-dv-section')) return null;
    var gi = parseInt(secEl.getAttribute('data-dv-section'), 10);
    if (isNaN(gi)) return null;
    var el = ev.target.closest('[data-dv-node], [data-dv-edge], [data-dv-step], [data-dv-panel], [data-dv-bullet], [data-dv-para], [data-dv-crow]');
    if (el && secEl.contains(el)){
      if (el.hasAttribute('data-dv-node'))
        return {section: gi, kind: 'node', id: el.getAttribute('data-dv-node'), el: el};
      if (el.hasAttribute('data-dv-step'))
        return {section: gi, kind: 'step', index: parseInt(el.getAttribute('data-dv-step'), 10), el: el};
      if (el.hasAttribute('data-dv-panel'))
        return {section: gi, kind: 'panel', index: parseInt(el.getAttribute('data-dv-panel'), 10), el: el};
      if (el.hasAttribute('data-dv-bullet'))
        return {section: gi, kind: 'bullet', index: parseInt(el.getAttribute('data-dv-bullet'), 10), el: el};
      if (el.hasAttribute('data-dv-para'))
        return {section: gi, kind: 'para', index: parseInt(el.getAttribute('data-dv-para'), 10), el: el};
      if (el.hasAttribute('data-dv-crow'))
        return {section: gi, kind: 'crow', index: parseInt(el.getAttribute('data-dv-crow'), 10), el: el};
      /* halo and label clicks resolve to the same edge — highlight the
         visible edge path (the halo has no selected style of its own) */
      var edgeIdx = parseInt(el.getAttribute('data-dv-edge'), 10);
      var edgeEl = secEl.querySelector('path.edge[data-dv-edge="' + edgeIdx + '"]') || el;
      return {section: gi, kind: 'edge', index: edgeIdx, el: edgeEl};
    }
    var groupEl = ev.target.closest('g.grp[data-dv-group]');
    if (groupEl && secEl.contains(groupEl))
      return {section: gi, kind: 'group', id: groupEl.getAttribute('data-dv-group'), el: groupEl};
    return {section: gi, kind: 'section', el: secEl};
  }

  function selectTarget(target, focusEditor, keepTool){
    clipboardHomeTarget=null;
    pausePreview();
    if (opts.workspace && !keepTool) opts.workspace.showTool('inspect', {closeUtilities:true});
    if (target.kind === 'group') clearMultiSelect(); /* this action establishes a single selection */
    setSelected(target.el);
    currentTarget = {section: target.section, kind: target.kind,
                     id: target.id, index: target.index,
                     block: target.block, tab: target.tab};
    if (target.kind !== 'tab') insertSection = target.section;
    var parsed = parseEditor();
    if (!parsed.error) updateTargetLabel(parsed.raw);
    syncBoardToSelectedStep();
    if (currentTarget.kind === 'step'){
      var sp = stepperFor(currentTarget.section);
      if (sp && sp.path) currentTarget.pathId = sp.path();
    }
    renderInspector();
    applyStepMarkers();
    if (stepList) stepList.sync();
    if(target.homeElement && !parsed.error){
      var panelPath=builderTargetPath(parsed.raw,currentTarget), home=panelPath && specValueAt(parsed.raw,panelPath), pick=target.homeElement;
      var item=pick.field === 'rooms' ? pick.item : home && (home[pick.field] || []).findIndex(function(x){return x.id === pick.id;});
      if(home && item>=0)homeClipboardSelect({kind:'home',section:target.section,index:target.index,field:pick.field,item:item});
    }
    if (focusEditor === false) return;
    var path = parsed.error ? null : builderTargetPath(parsed.raw, currentTarget);
    var loc = path ? jsonLocate(src.value, path) : null;
    if (loc) selectRange(loc);
  }

  /* ---- searchable document outline ---- */
  var outline = document.getElementById('sec-outline');
  var outlineSearch = document.getElementById('outline-search');
  var outlineResults = document.getElementById('outline-results');
  var outlineStatus = document.getElementById('outline-status');
  function refreshOutline(){
    if (!outlineResults) return;
    outlineResults.innerHTML = '';
    var indexedText = src.value;
    var entries;
    try { entries = builderOutline(JSON.parse(src.value), outlineSearch.value); }
    catch (ex){ outlineStatus.textContent = 'Fix the JSON source to browse its outline.'; return; }
    outlineStatus.textContent = entries.length ? Math.min(entries.length, 200) + ' of ' + entries.length + ' items' : 'No matching items';
    entries.slice(0, 200).forEach(function(entry){
      var button = document.createElement('button');
      button.type = 'button'; button.className = 'outline-item';
      var title = document.createElement('span'); title.textContent = entry.target.kind + ' · ' + entry.label;
      var sub = document.createElement('small'); sub.textContent = entry.context;
      button.appendChild(title); button.appendChild(sub);
      button.title = builderPathString(entry.path);
      button.addEventListener('click', function(){
        if (addToStep) return;
        if (src.value !== indexedText){
          refreshOutline();
          outlineStatus.textContent = 'Source changed; outline refreshed. Select the item again.';
          return;
        }
        /* Never map fresh JSON onto stale rendered section ordinals. */
        if (opts.renderedText && opts.renderedText() !== src.value){
          render();
          if (opts.renderedText() !== src.value){ inspectorMessage('Fix validation errors before navigating the preview.'); return; }
        }
        if (connect) cancelConnect(null);
        clearMultiSelect();
        if (entry.tab){
          var tabButton = document.getElementById('tab-' + entry.tab.block + '-' + entry.tab.tab);
          if (tabButton) tabButton.click();
        }
        var el = findTargetEl(entry.target);
        selectTarget(Object.assign({}, entry.target, {el: el}), false);
        var loc = jsonLocate(src.value, entry.path);
        if (loc && sourceVisible()){
          src.setSelectionRange(loc.start, loc.end);
          scrollTextareaTo(loc.start);
        }
        if (el) el.scrollIntoView({block: 'nearest', behavior: 'auto'});
      });
      outlineResults.appendChild(button);
    });
  }
  if (outlineSearch){
    outlineSearch.addEventListener('input', refreshOutline);
    outlineSearch.addEventListener('keydown', function(ev){
      if ((ev.key === 'ArrowDown' || ev.key === 'Enter') && outlineResults.firstChild){
        ev.preventDefault(); outlineResults.firstChild.focus();
      }
    });
    var outlineTimer;
    src.addEventListener('input', function(){ clearTimeout(outlineTimer); outlineTimer = setTimeout(refreshOutline, 200); });
    new MutationObserver(refreshOutline).observe(view, {childList: true});
    document.addEventListener('keydown', function(ev){
      if (!(ev.metaKey || ev.ctrlKey) || ev.altKey || ev.key.toLowerCase() !== 'k' || addToStep) return;
      ev.preventDefault();
      if (specbox) specbox.open = true;
      outline.open = true; outlineSearch.focus(); outlineSearch.select();
    });
    refreshOutline();
  }

  /* The step list shares this builder's selection, render and undo pipeline. */
  var stepList = typeof initWorkbenchStepList === 'function' ? initWorkbenchStepList({
    view:view, src:src, renderedText:opts.renderedText,
    configure:function(plan, section){
      /* A previous inspector selection must not pull settings back to another section. */
      if (currentTarget && currentTarget.section !== section){
        currentTarget=null; setSelected(null); clearMultiSelect(); if (guide) guide.hidden=true;
      }
      return applyPlan(plan);
    },
    pause:pausePreview,
    inspect:function(){ if (opts.workspace) opts.workspace.showTool('inspect', {focus:true}); },
    selection:function(){ return currentTarget; },
    locked:function(){ return !!addToStep || !!connect; },
    path:function(section){var sp=stepperFor(section);return sp && sp.path();},
    selectPath:function(section,id){
      currentTarget=null; clearMultiSelect(); if(guide) guide.hidden=true;
      var sp=stepperFor(section); if(sp) sp.selectPath(id);
      applyRowGrabs(); clearStepMarkers();
    },
    navigate:function(entry){
      clearMultiSelect();
      if (entry.tab){
        var tabButton = document.getElementById('tab-' + entry.tab.block + '-' + entry.tab.tab);
        if (tabButton) tabButton.click();
      }
      if(entry.pathId){var sp=stepperFor(entry.target.section);if(sp) sp.selectPath(entry.pathId,entry.position);}
      var el = findTargetEl(entry.target);
      selectTarget(Object.assign({}, entry.target, {el:el}), false, true);
      var loc = jsonLocate(src.value, entry.path);
      if (loc && sourceVisible()){
        src.setSelectionRange(loc.start, loc.end); scrollTextareaTo(loc.start);
      }
      if (el) el.scrollIntoView({block:'nearest', behavior:'auto'});
    },
    apply:function(plan, section){
      clearMultiSelect();
      return applyPlan(plan, {after:function(){
        var story = builderStorySections(JSON.parse(src.value)).find(function(entry){ return entry.section === section; });
        if (story && story.tab){
          var tabButton = document.getElementById('tab-' + story.tab.block + '-' + story.tab.tab);
          if (tabButton) tabButton.click();
        }
        currentTarget = {kind:'step', section:section, index:plan.index};
        if(plan.pathId){currentTarget.pathId=plan.pathId;var sp=stepperFor(section);if(sp) sp.jumpSource(plan.index,plan.pathId);}
        insertSection = section;
        renderInspector();
      }});
    }
  }) : null;

  var sectionLayoutEditor=typeof initSectionLayoutEditor === 'function' ? initSectionLayoutEditor({
    view:view,src:src,ctl:opts.ctl,render:render,renderedText:opts.renderedText,pause:pausePreview,
    locked:function(){return !!addToStep || !!connect;},
    commit:function(section,target,items){
      return commitCascade(function(raw){return planSectionLayout(src.value,raw,section,target,items);});
    },
    rename:function(section,name){
      return commitCascade(function(raw){return planSectionLayoutName(src.value,raw,section,name);});
    }
  }) : null;
